        s1 = c_green; s2 = c_green; std_badge_color = c_blue;
        s3a = frm.doc.custom_finance_approved ? c_green : c_blue; s3b = frm.doc.custom_hr_approved ? c_green : c_blue; s3c = frm.doc.custom_legal_approved ? c_green : c_blue;
    } 
    else if (status === 'Finance Rejected') { s1 = c_green; s2 = c_green; s3a = c_red; std_badge_color = c_red; s3b = frm.doc.custom_hr_approved ? c_green : c_gray; s3c = frm.doc.custom_legal_approved ? c_green : c_gray; } 
    else if (status === 'HR Rejected') { s1 = c_green; s2 = c_green; s3b = c_red; std_badge_color = c_red; s3a = frm.doc.custom_finance_approved ? c_green : c_gray; s3c = frm.doc.custom_legal_approved ? c_green : c_gray; } 
    else if (status === 'Legal Rejected') { s1 = c_green; s2 = c_green; s3c = c_red; std_badge_color = c_red; s3a = frm.doc.custom_finance_approved ? c_green : c_gray; s3b = frm.doc.custom_hr_approved ? c_green : c_gray; } 
    else if (['Internally Approved', 'Pending Final Approval'].includes(status)) { s1 = c_green; s2 = c_green; s3a = c_green; s3b = c_green; s3c = c_green; std_badge_color = c_blue; s4 = c_blue; }
    else if (status === 'Final Rejected') { s1 = c_green; s2 = c_green; s3a = c_green; s3b = c_green; s3c = c_green; std_badge_color = c_red; s4 = c_red; }

    let level_2_html = `
