                <div style="flex: 1; text-align: center;"><div style="height: 10px; background: ${s2}; border-radius: 5px; transition: 0.5s;"></div><div style="font-size: 11px; font-weight: 700; color: #475569; margin-top: 8px;">Level 1: Lead</div></div>
                <div style="display: flex; flex-direction: column; flex: 1.5; background: white; padding: 12px; border-radius: 8px; border: 1px dashed #cbd5e1;">${level_2_html}</div>
                <div style="flex: 1; text-align: center;"><div style="height: 10px; background: ${s4}; border-radius: 5px; transition: 0.5s;"></div><div style="font-size: 11px; font-weight: 700; color: #475569; margin-top: 8px;">Final Approval</div></div>
            </div>
        </div>`;
        
    // ----------------------------------------------------
    // 4. COMBINE AND RENDER
