        function sync_row_heights(el) {
            if (!el) return;
            let $row = $(el).closest('.data-row');
            if (!$row.length) return;

            // Step 1: Reset heights temporarily to 48px baseline so scrollHeight reflects true content height
            $row.find('textarea').each(function() {
                this.style.setProperty('height', '48px', 'important');
                this.style.setProperty('min-height', '48px', 'important');
            });
            $row.find('.static-area').each(function() {
                this.style.setProperty('height', 'auto', 'important');
                this.style.setProperty('min-height', '48px', 'important');
            });
            $row.find('.col, .grid-static-col, .field-area, .control-input, .control-input-wrapper').each(function() {
                this.style.setProperty('min-height', '48px', 'important');
            });

            // Step 2: Measure natural content scrollHeight
            let max_h = 48;

            $row.find('textarea').each(function() {
                this.style.setProperty('height', 'auto', 'important');
                let sh = this.scrollHeight || 0;
                if (sh > max_h) {
                    max_h = sh;
                }
            });

            $row.find('.static-area').each(function() {
                let sh = this.scrollHeight || 0;
                if (sh > max_h) {
                    max_h = sh;
                }
            });

            // Clean natural height without cumulative runaway inflation
            max_h = Math.max(48, Math.ceil(max_h));

            // Step 3: Apply synchronized height across all cells in this row
            $row.css('min-height', max_h + 'px');
            $row.find('.col, .grid-static-col, .field-area, .control-input, .control-input-wrapper').each(function() {
                this.style.setProperty('min-height', max_h + 'px', 'important');
            });

            $row.find('textarea').each(function() {
                this.style.setProperty('height', max_h + 'px', 'important');
                this.style.setProperty('min-height', max_h + 'px', 'important');
            });

            $row.find('.static-area').each(function() {
                this.style.setProperty('height', 'auto', 'important');
                this.style.setProperty('min-height', max_h + 'px', 'important');
            });
        }

        $(document).off('input.comp_grow focus.comp_grow keyup.comp_grow paste.comp_grow change.comp_grow', '[data-fieldname="custom_objectives__achievements"] textarea')
                   .on('input.comp_grow focus.comp_grow keyup.comp_grow paste.comp_grow change.comp_grow', '[data-fieldname="custom_objectives__achievements"] textarea', function() {
            sync_row_heights(this);
        });

        let $obj_tbl = $(frm.fields_dict.custom_objectives__achievements?.wrapper);
        if ($obj_tbl.length) {
            $obj_tbl.off('click.auto_grow').on('click.auto_grow', '.grid-row', function() {
                setTimeout(() => {
                    sync_row_heights(this);
                }, 50);
            });
        }

        if (frm.fields_dict.custom_objectives__achievements && frm.fields_dict.custom_objectives__achievements.grid) {
            let grid = frm.fields_dict.custom_objectives__achievements.grid;
            grid.grid_rows.forEach(row => {
