    before_workflow_action: function(frm) {
        let action = frm.selected_workflow_action;
        if (['Reject Objectives', 'Reject Mid-Term', 'Reject'].includes(action)) {
            frappe.dom.unfreeze();
            return new Promise((resolve, reject) => {
                let submitted = false;
                let dialog = new frappe.ui.Dialog({
                    title: __('Reason for Rejection'),
                    fields: [
                        {
                            label: __('Please state the reason for rejecting this appraisal:'),
                            fieldname: 'reason',
                            fieldtype: 'Small Text',
                            reqd: 1
                        }
                    ],
                    primary_action_label: __('Reject'),
                    primary_action: function(values) {
                        if (!values.reason || !values.reason.trim()) {
                            frappe.msgprint(__('Please enter a reason for rejection.'));
                            return;
                        }
                        submitted = true;
                        frm.doc.custom_rejection_reason = values.reason.trim();
                        dialog.hide();
                        frappe.dom.freeze();
                        resolve();
                    }
                });

                dialog.on_hide = function() {
                    if (!submitted) {
                        frappe.dom.unfreeze();
                        reject();
                    }
                };

                dialog.show();
            });
        }

        if (action === 'Approve Mid-Term') {
            let mid_fb = (frm.doc.custom_midterm_manager_feedback || '').trim();
            if (!mid_fb) {
                frappe.dom.unfreeze();
                frappe.msgprint({
                    title: __('Manager Feedback Required'),
                    indicator: 'orange',
                    message: __('Please provide <b>Mid Term Appraisal: Manager assessment/feedback</b> before approving the mid-term appraisal.')
                });
                frm.scroll_to_field('custom_midterm_manager_feedback');
                return Promise.reject();
            }
        }

        if (action === 'Finalize & Complete') {
            let fb = (frm.doc.custom_annual_manager_feedback || '').trim();
            let rating = (frm.doc.custom_annual_manager_rating || '').trim();

            if (!fb) {
                frappe.dom.unfreeze();
                frappe.msgprint({
                    title: __('Feedback Required'),
                    indicator: 'orange',
                    message: __('Please provide <b>Annual Appraisal: Manager assessment/feedback</b> in the <b>Manager Feedback</b> tab before completing the appraisal.')
                });
                frm.layout.tabs.find(t => t.df.fieldname === 'feedback_tab')?.show();
                return Promise.reject();
            }

            if (!rating) {
                frappe.dom.unfreeze();
                frappe.msgprint({
                    title: __('Rating Required'),
                    indicator: 'orange',
                    message: __('Please select an <b>Annual Manager Rating</b> in the <b>Manager Feedback</b> tab before completing the appraisal.')
                });
                frm.layout.tabs.find(t => t.df.fieldname === 'feedback_tab')?.show();
                return Promise.reject();
            }

            let unrated = [];
            ['custom_behavioural_competencies', 'custom_executive_technical_competencies', 'custom_leadership_technical_competencies'].forEach(name => {
                (frm.doc[name] || []).forEach(r => {
                    let r_rate = (r.annual_rating || '').trim();
                    if (!r_rate) {
                        unrated.push(r.competency_name || 'Competency');
                    }
                });
            });

            if (unrated.length > 0) {
                frappe.dom.unfreeze();
                let displayList = unrated.slice(0, 5).join('<br>• ');
                if (unrated.length > 5) {
                    displayList += `<br>... and ${unrated.length - 5} more`;
                }
                frappe.msgprint({
                    title: __('Competency Ratings Required'),
                    indicator: 'orange',
                    message: __('Please provide <b>Annual Ratings</b> for all Technical & Behavioural Competencies before completing the appraisal.<br><br><b>Unrated competencies:</b><br>• ' + displayList)
                });
                frm.layout.tabs.find(t => t.df.fieldname === 'custom_technical__behavio')?.show();
                return Promise.reject();
            }
        }
    },

    employee: function(frm) {
        if (frm.doc.employee) {
            frappe.db.get_value('Employee', frm.doc.employee, ['reports_to', 'user_id', 'company']).then(r => {
                if (r && r.message) {
                    if (r.message.company) {
                        frm.set_value('company', r.message.company);
                    }
                    if (r.message.reports_to) {
                        frm.set_value('custom_manager', r.message.reports_to);
                        frappe.db.get_value('Employee', r.message.reports_to, 'user_id').then(mr => {
                            if (mr && mr.message && mr.message.user_id) {
                                frm.set_value('custom_manager_email', mr.message.user_id);
                            }
                        });
                    }
                    if (r.message.user_id) {
                        frm.set_value('custom_employee_email', r.message.user_id);
                    }
                }
                apply_css_tab_isolation(frm);
                apply_manager_security_lock(frm);
                enforce_field_visibility(frm);
            });
        }
    },

    appraisal_cycle: function(frm) {
        if (frm.doc.appraisal_cycle) {
            frappe.db.get_value('Appraisal Cycle', frm.doc.appraisal_cycle, ['status', 'custom_cycle_type'])
            .then(r => {
                if (r && r.message && r.message.status !== 'In Progress') {
                    frappe.msgprint({ title: __('Cycle Not Started'), indicator: 'red', message: __('Please start the Appraisal Cycle first.') });
                    frm.set_value('appraisal_cycle', ''); 
                } else {
                    if (r && r.message) frm._cycle_type = r.message.custom_cycle_type;
                    apply_manager_security_lock(frm);
                    setup_competencies(frm);
                    enforce_field_visibility(frm);
                    sync_status_columns(frm);
                    render_progress_bar(frm);
                    force_correct_header_badge(frm);
                }
            });
        } else {
            enforce_field_visibility(frm);
        }
    },

    validate: function(frm) {
        let state = frm.doc.workflow_state || 'Pending';
        let is_employee = (frappe.session.user === frm.doc.custom_employee_email || frappe.session.user === frm.doc.employee_email);
        if (!is_employee && state === 'Pending Manager Review') {
            if (!frm.doc.custom_annual_manager_rating) {
                frappe.msgprint({
                    title: __('Rating Required'),
                    indicator: 'red',
                    message: __('Please select an Annual Manager Rating before finalizing.')
                });
                frappe.validated = false;
            }
        }
    }
});

function sync_status_columns(frm) {
    let state = frm.doc.workflow_state || 'Pending';
    let obj_st = 'Pending';
    let mid_st = 'Pending';
    let ann_st = 'Pending';

    if (state === 'Objective Review Pending') {
        obj_st = 'Under Review';
    } else if (state === 'Objectives Rejected') {
        obj_st = 'Rejected';
    } else if (state === 'Objectives Approved') {
        obj_st = 'Approved';
    } else if (state === 'Mid-Term Review Pending') {
        obj_st = 'Approved';
        mid_st = 'Under Review';
    } else if (state === 'Mid-Term Rejected') {
        obj_st = 'Approved';
        mid_st = 'Rejected';
    } else if (state === 'Mid-Term Completed') {
        obj_st = 'Approved';
        mid_st = 'Completed';
    } else if (state === 'Pending Manager Review') {
        obj_st = 'Approved';
        mid_st = 'Completed';
        ann_st = 'Under Review';
    } else if (state === 'Appraisal Rejected') {
        obj_st = 'Approved';
        mid_st = 'Completed';
        ann_st = 'Rejected';
    } else if (state === 'Completed') {
        obj_st = 'Approved';
        mid_st = 'Completed';
        ann_st = 'Completed';
    }

    if (frm.doc.custom_objective_status !== obj_st) {
        frm.doc.custom_objective_status = obj_st;
        if (frm.fields_dict.custom_objective_status) frm.refresh_field('custom_objective_status');
    }
    if (frm.doc.custom_midterm_status !== mid_st) {
        frm.doc.custom_midterm_status = mid_st;
        if (frm.fields_dict.custom_midterm_status) frm.refresh_field('custom_midterm_status');
    }
    if (frm.doc.custom_annual_status !== ann_st) {
        frm.doc.custom_annual_status = ann_st;
        if (frm.fields_dict.custom_annual_status) frm.refresh_field('custom_annual_status');
    }
}

function lock_and_clean_overview_tab(frm) {
    let is_new = frm.is_new();
    let fields = [
        'appraisal_template', 'company', 'department', 'designation',
        'employee_name', 'start_date', 'end_date',
        'custom_employee_email', 'custom_manager', 'custom_manager_email',
        'custom_objective_status', 'custom_midterm_status', 'custom_annual_status'
    ];
    fields.forEach(f => {
        if (frm.fields_dict[f]) frm.set_df_property(f, 'read_only', 1);
    });

    // Allow selecting Employee when creating a new Appraisal form
    if (frm.fields_dict.employee) {
        frm.set_df_property('employee', 'read_only', is_new ? 0 : 1);
    }

    if (frm.fields_dict.custom_cycle_type) {
        frm.set_df_property('custom_cycle_type', 'hidden', 1);
    }
}

function set_field_state(frm, fieldname, hidden, read_only, label, reqd) {
    if (!frm.fields_dict[fieldname]) return;
    if (hidden !== undefined) {
        frm.set_df_property(fieldname, 'hidden', hidden ? 1 : 0);
        if (frm.toggle_display) frm.toggle_display(fieldname, !hidden);
    }
    if (read_only !== undefined) {
        frm.set_df_property(fieldname, 'read_only', read_only ? 1 : 0);
    }
    if (label !== undefined && label !== null) {
        frm.set_df_property(fieldname, 'label', label);
    }
    if (reqd !== undefined) {
        frm.set_df_property(fieldname, 'reqd', reqd ? 1 : 0);
    }

    let $wrapper = $(frm.fields_dict[fieldname].wrapper);
    if ($wrapper.length) {
        if (hidden) {
            $wrapper.hide().addClass('hide');
        } else {
            $wrapper.show().removeClass('hide');
        }
    }
}

function set_section_state(frm, section_fieldname, hidden, label) {
    if (!frm.fields_dict[section_fieldname]) return;
    if (hidden !== undefined) {
        frm.set_df_property(section_fieldname, 'hidden', hidden ? 1 : 0);
        if (frm.toggle_display) frm.toggle_display(section_fieldname, !hidden);
    }
    if (label !== undefined && label !== null) {
        frm.set_df_property(section_fieldname, 'label', label);
    }
    let $wrapper = $(frm.fields_dict[section_fieldname].wrapper);
    if ($wrapper.length) {
        if (hidden) {
            $wrapper.hide().addClass('hide');
        } else {
            $wrapper.show().removeClass('hide');
        }
    }
}


function get_user_role_context(frm) {
    let session_user = (frappe.session.user || '').trim().toLowerCase();
    let emp_email = (frm.doc.custom_employee_email || frm.doc.employee_email || '').trim().toLowerCase();
    let mgr_email = (frm.doc.custom_manager_email || '').trim().toLowerCase();

    let is_admin = (
        session_user === 'administrator' || 
        frappe.user_roles.includes('Administrator') || 
        frappe.user_roles.includes('System Manager') ||
        frappe.user_roles.includes('HR Manager') ||
        frappe.user_roles.includes('HR User')
    );

    let is_actual_emp = false;
    if (emp_email && session_user === emp_email) {
        is_actual_emp = true;
    } else if (frm.doc.employee && frappe.boot && frappe.boot.user && frappe.boot.user.employee === frm.doc.employee) {
        is_actual_emp = true;
    }

    let is_mgr = false;
    if (mgr_email && session_user === mgr_email) {
        is_mgr = true;
    }

    // Line manager must never be treated as the employee
    let is_emp = is_actual_emp;
    if (!is_admin && !is_mgr) {
        is_emp = true;
    }

    return {
        is_admin: is_admin,
        is_employee: is_emp,
        is_actual_employee: is_actual_emp,
        is_line_manager: is_mgr
    };
}

function apply_css_tab_isolation(frm) {
    $('#appraisal-tab-isolation-css').remove();
    if (!frm || !frm.doc) return;

    let ctx = get_user_role_context(frm);
    let state = frm.doc.workflow_state || 'Pending';

    // Technical & Behavioural Competencies is ONLY visible to Line Manager and HR/Admin after annual submission ('Pending Manager Review' or 'Completed').
    // The employee must NEVER see this tab (not in mid-term, not in annual, and not in completed).
    // Technical & Behavioural Competencies tab:
    // Strictly HIDDEN from the employee at all times (including HR on their own appraisal).
    // ONLY visible to Line Manager or HR/Admin on OTHER employees' appraisals during 'Pending Manager Review' and 'Completed'.
    let can_see_competencies = false;
    if (ctx.is_actual_employee) {
        can_see_competencies = false;
    } else if ((ctx.is_line_manager || ctx.is_admin) && ['Pending Manager Review', 'Completed'].includes(state)) {
        can_see_competencies = true;
    }
    let hide_competencies = !can_see_competencies;

    // Manager Feedback tab:
    // Visible to Line Manager and HR/Admin during review stages ('Mid-Term Review Pending', 'Pending Manager Review').
    // When Completed: VISIBLE to everyone (including Employee, read-only) so the employee can view the manager's annual feedback and rating!
    let can_see_feedback = false;
    if (state === 'Completed') {
        can_see_feedback = true;
    } else if (['Mid-Term Review Pending', 'Pending Manager Review'].includes(state) && (ctx.is_line_manager || ctx.is_admin)) {
        can_see_feedback = true;
    }
    let hide_feedback = !can_see_feedback;

    let css = '';
    if (hide_competencies) {
        css += `
            .form-tabs li:has([data-fieldname="custom_technical__behavio"]),
            .form-tabs li:has(#appraisal-custom_technical__behavio-tab),
            .form-tabs [data-fieldname="custom_technical__behavio"],
            #appraisal-custom_technical__behavio-tab,
            #appraisal-custom_technical__behavio,
            .tab-pane[id*="custom_technical__behavio"] {
                display: none !important;
                visibility: hidden !important;
            }
        `;
    }
    if (hide_feedback) {
        css += `
            .form-tabs li:has([data-fieldname="feedback_tab"]),
            .form-tabs li:has(#appraisal-feedback_tab-tab),
            .form-tabs [data-fieldname="feedback_tab"],
            #appraisal-feedback_tab-tab,
            #appraisal-feedback_tab,
            .tab-pane[id*="feedback_tab"] {
                display: none !important;
                visibility: hidden !important;
            }
        `;
    }

    css += `
        .form-tabs li:has([data-fieldname="kra_tab"]),
        .form-tabs li:has(#appraisal-kra_tab-tab),
        .form-tabs [data-fieldname="kra_tab"],
        #appraisal-kra_tab-tab,
        #appraisal-kra_tab,
        .tab-pane[id*="kra_tab"] {
            display: none !important;
            visibility: hidden !important;
        }
    `;

    if (css) {
        $('head').append(`<style id="appraisal-tab-isolation-css">${css}</style>`);
    }

    set_tab_state('custom_technical__behavio', !hide_competencies, frm);
    set_tab_state('feedback_tab', !hide_feedback, frm);
    set_tab_state('kra_tab', false, frm);
}

