function set_tab_state(tab_fieldname, visible, frm) {
    let form = frm || cur_frm;
    if (!form) return;

    if (form.set_df_property) {
        form.set_df_property(tab_fieldname, 'hidden', visible ? 0 : 1);
    }
    let df = frappe.meta.get_docfield('Appraisal', tab_fieldname);
    if (df) {
        df.hidden = visible ? 0 : 1;
    }

    if (form.layout && form.layout.tabs) {
        form.layout.tabs.forEach(tab => {
            if (tab.df && (tab.df.fieldname === tab_fieldname || tab.df.label === tab_fieldname)) {
                tab.df.hidden = visible ? 0 : 1;
                tab.toggle(visible);
            }
        });
    }

    let $tab_links = $(`.form-tabs a[href*="${tab_fieldname}"], .form-tabs a[id*="${tab_fieldname}"], [data-fieldname="${tab_fieldname}"]`);
    let $tab_btn = $tab_links.closest('.nav-item, li');
    let $tab_pane = $(`#appraisal-${tab_fieldname}, [id*="${tab_fieldname}"].tab-pane`);

    if (visible) {
        $tab_links.show().removeClass('hide hidden').css({'display': '', 'visibility': 'visible'});
        $tab_btn.show().removeClass('hide hidden').css({'display': '', 'visibility': 'visible'});
        $tab_pane.removeClass('hide hidden').css({'visibility': 'visible'});
    } else {
        $tab_links.hide().addClass('hide hidden').css({'display': 'none', 'visibility': 'hidden'});
        $tab_btn.hide().addClass('hide hidden').css({'display': 'none', 'visibility': 'hidden'});
        $tab_pane.addClass('hide hidden').css({'display': 'none', 'visibility': 'hidden'});

        if ($tab_btn.find('.nav-link.active').length || $tab_pane.hasClass('active')) {
            $tab_btn.find('.nav-link').removeClass('active');
            $tab_pane.removeClass('active show');
            $('[data-fieldname="self_appraisal_tab"]').closest('.nav-item').find('.nav-link').tab('show');
        }
    }

    $('.form-tabs .nav-link').each(function() {
        let t = $(this).text().trim().toLowerCase();
        if (tab_fieldname === 'custom_technical__behavio' && t.includes('technical & behavioural')) {
            if (visible) {
                $(this).closest('li').show().removeClass('hide hidden').css('display', '');
            } else {
                $(this).closest('li').hide().addClass('hide hidden').css('display', 'none');
            }
        }
        if (tab_fieldname === 'feedback_tab' && t.includes('manager feedback')) {
            if (visible) {
                $(this).closest('li').show().removeClass('hide hidden').css('display', '');
            } else {
                $(this).closest('li').hide().addClass('hide hidden').css('display', 'none');
            }
        }
    });
}

function safe_grid_update(grid, fieldname, prop, val) {
    if (grid && grid.get_docfield && grid.get_docfield(fieldname)) {
        try {
            grid.update_docfield_property(fieldname, prop, val);
        } catch (e) {}
    }
}

function move_field(frm, field_to_move, target_field, position) {
    if (!frm.fields_dict[field_to_move] || !frm.fields_dict[target_field]) return;
    const $field = $(frm.fields_dict[field_to_move].wrapper);
    const $target = $(frm.fields_dict[target_field].wrapper);
    if ($field.length && $target.length) {
        if (position === 'after') {
            $field.insertAfter($target);
        } else if (position === 'before') {
            $field.insertBefore($target);
        }
    }
}

function enforce_field_visibility(frm) {
    let ctx = get_user_role_context(frm);
    let is_employee = ctx.is_employee;
    let is_admin = ctx.is_admin;
    let state = frm.doc.workflow_state || 'Pending';

    let cycle_name = (frm.doc.appraisal_cycle || '').toLowerCase();
    let cycle_type = frm._cycle_type || (frm.doc && frm.doc.custom_cycle_type) || '';
    // Permanent cleanup of obsolete fields & tabs
    set_field_state(frm, 'custom_linked_midterm_appraisal', true);
    set_field_state(frm, 'custom_manager_review__feedback', true);
    set_field_state(frm, 'custom_midterm_context', true);
    set_field_state(frm, 'self_ratings', true);
    set_tab_state('kra_tab', false);
    apply_objectives_grid_isolation(frm);

    // -----------------------------------------------------------------
    // DETERMINE ACTIVE PHASE IN UNIFIED SINGLE-CYCLE WORKFLOW
    // -----------------------------------------------------------------
    let is_phase_1 = false; // Objectives
    let is_phase_2 = false; // Mid Term Appraisal
    let is_phase_3 = false; // Annual Appraisal

    if (!frm.doc.workflow_state || ['Pending', 'Draft', 'Objective Review Pending', 'Objectives Rejected'].includes(state)) {
        is_phase_1 = true;
    } else if (['Objectives Approved', 'Mid-Term Review Pending', 'Mid-Term Rejected'].includes(state)) {
        is_phase_2 = true;
    } else {
        // 'Mid-Term Completed', 'Pending Manager Review', 'Appraisal Rejected', 'Completed'
        is_phase_3 = true;
    }

    // STRICT PERMISSIONS:
    // Only actual employee can edit self-appraisal fields (objectives, achievements, reflections).
    // Line Manager (even with admin roles) can NEVER edit employee self-appraisal fields!
    let can_edit_obj = (ctx.is_actual_employee || (ctx.is_admin && !ctx.is_line_manager)) && (!frm.doc.workflow_state || ['Pending', 'Draft', 'Objectives Rejected'].includes(state));
    let can_edit_midterm_self = ctx.is_actual_employee && ['Objectives Approved', 'Mid-Term Rejected'].includes(state);
    let can_edit_mgr_mid = (ctx.is_line_manager || (ctx.is_admin && !ctx.is_actual_employee)) && (state === 'Mid-Term Review Pending');

    let can_edit_annual_self = ctx.is_actual_employee && ['Mid-Term Completed', 'Appraisal Rejected'].includes(state);
    let can_edit_mgr_ann = (ctx.is_line_manager || (ctx.is_admin && !ctx.is_actual_employee)) && (state === 'Pending Manager Review');
    let can_edit_dev_needs = can_edit_annual_self || can_edit_mgr_ann;

    // -----------------------------------------------------------------
    // 1. OBJECTIVES & ACHIEVEMENTS GRID COLUMNS
    // -----------------------------------------------------------------
    if (frm.fields_dict.custom_objectives__achievements && frm.fields_dict.custom_objectives__achievements.grid) {
        let grid = frm.fields_dict.custom_objectives__achievements.grid;

        if (is_phase_1) {
            safe_grid_update(grid, 'objective', 'read_only', can_edit_obj ? 0 : 1);
            safe_grid_update(grid, 'plan_to_achieve', 'read_only', can_edit_obj ? 0 : 1);
            safe_grid_update(grid, 'how_will_you_achieve', 'read_only', can_edit_obj ? 0 : 1);
            safe_grid_update(grid, 'midterm_achievements', 'hidden', 1);
            safe_grid_update(grid, 'annual_achievements', 'hidden', 1);
            safe_grid_update(grid, 'midterm_achievements', 'read_only', 1);
            safe_grid_update(grid, 'annual_achievements', 'read_only', 1);
            grid.cannot_add_rows = !can_edit_obj;
            if (grid.wrapper) {
                grid.wrapper.find('.grid-add-row').toggle(can_edit_obj);
            }
        } else if (is_phase_2) {
            safe_grid_update(grid, 'objective', 'read_only', can_edit_midterm_self ? 0 : 1);
            safe_grid_update(grid, 'plan_to_achieve', 'read_only', can_edit_midterm_self ? 0 : 1);
            safe_grid_update(grid, 'how_will_you_achieve', 'read_only', can_edit_midterm_self ? 0 : 1);
            safe_grid_update(grid, 'midterm_achievements', 'hidden', 0);
            safe_grid_update(grid, 'midterm_achievements', 'read_only', can_edit_midterm_self ? 0 : 1);
            safe_grid_update(grid, 'annual_achievements', 'hidden', 1);
            safe_grid_update(grid, 'annual_achievements', 'read_only', 1);
            grid.cannot_add_rows = !can_edit_midterm_self;
            if (grid.wrapper) {
                grid.wrapper.find('.grid-add-row').toggle(can_edit_midterm_self);
            }
        } else if (is_phase_3) {
            safe_grid_update(grid, 'objective', 'read_only', can_edit_annual_self ? 0 : 1);
            safe_grid_update(grid, 'plan_to_achieve', 'read_only', can_edit_annual_self ? 0 : 1);
            safe_grid_update(grid, 'how_will_you_achieve', 'read_only', can_edit_annual_self ? 0 : 1);
            safe_grid_update(grid, 'midterm_achievements', 'hidden', 0);
            safe_grid_update(grid, 'midterm_achievements', 'read_only', 1);
            safe_grid_update(grid, 'annual_achievements', 'hidden', 0);
            safe_grid_update(grid, 'annual_achievements', 'read_only', can_edit_annual_self ? 0 : 1);
            grid.cannot_add_rows = !can_edit_annual_self;
            if (grid.wrapper) {
                grid.wrapper.find('.grid-add-row').toggle(can_edit_annual_self);
            }
        }

        // Reset visible_columns so all columns for active phase get proper headers
        grid.visible_columns = null;
        grid.setup_visible_columns();
        grid.make_head();
        grid.refresh();

        // Always keep rows inline and disable row popup modal form
        grid.wrapper.find('.btn-open-row').hide();
        grid.grid_rows.forEach(row => {
            if (row.is_open) row.toggle_view(false);
            row.wrapper.find('.row-index, .btn-open-row').off('click.prevent_popup').on('click.prevent_popup', function(e) {
                e.stopImmediatePropagation();
                return false;
            });
            row.toggle_view = function() { return this; };
        });
        setTimeout(() => {
            let $tbl = $(frm.fields_dict.custom_objectives__achievements.wrapper);
            if ($tbl.length) {
                $tbl.find('[data-fieldname="midterm_achievements"]').toggle(!is_phase_1);
                $tbl.find('[data-fieldname="annual_achievements"]').toggle(is_phase_3);
            }
        }, 100);
    }

    // -----------------------------------------------------------------
    // 2. PHASE 1 (OBJECTIVES) FIELD VISIBILITY
    // -----------------------------------------------------------------
    if (is_phase_1) {
        // HIDE ALL Mid-Term and Annual fields
        set_field_state(frm, 'custom_midterm_employee_upward_feedback', true);
        set_field_state(frm, 'custom_midterm_manager_feedback', true);
        set_section_state(frm, 'reflections_section', true);
        set_field_state(frm, 'custom_self_assessment_on_annual_progress', true);
        set_field_state(frm, 'custom_upward_feedback_to_manager', true);
        set_field_state(frm, 'custom_annual_employee_performance_development_needs', true);
        set_field_state(frm, 'custom_annual_manager_feedback', true);
        set_field_state(frm, 'custom_rating_instructions', true);
        set_field_state(frm, 'custom_annual_manager_rating', true);

        // Hide tabs
        set_tab_state('custom_technical__behavio', false);
        set_tab_state('feedback_tab', false);
    }

    // -----------------------------------------------------------------
    // 3. PHASE 2 (MID TERM APPRAISAL) FIELD VISIBILITY
    // -----------------------------------------------------------------
    else if (is_phase_2) {
        // Reveal Mid-Term Self-Appraisal
        set_field_state(
            frm, 
            'custom_midterm_employee_upward_feedback', 
            false, 
            can_edit_midterm_self ? 0 : 1, 
            '<b>Mid Term Appraisal: Self-appraisal</b><br><span style="font-weight: normal; font-size: 12px; color: #687684;">Please summarise key achievements till mid-term – what has gone well, and which areas need improvement.</span>'
        );
        move_field(frm, 'custom_midterm_employee_upward_feedback', 'custom_objectives__achievements', 'after');

        // Reveal Mid-Term Manager Feedback ONLY when Review Pending or Completed
        let show_mgr_mid = (state === 'Mid-Term Review Pending' || state === 'Completed');
        if (show_mgr_mid) {
            set_field_state(
                frm, 
                'custom_midterm_manager_feedback', 
                false, 
                can_edit_mgr_mid ? 0 : 1, 
                '<b>Mid Term Appraisal: Manager assessment/feedback</b><br><span style="font-weight: normal; font-size: 12px; color: #687684;">Please highlight any specific areas and feedback in line with the above self-appraisal. Please also include any agreed amendments to the current objectives if applicable which will become part of the annual review process.</span>'
            );
            set_tab_state('feedback_tab', true);
        } else {
            set_field_state(frm, 'custom_midterm_manager_feedback', true);
            set_tab_state('feedback_tab', false);
        }

        // HIDE ALL Annual fields
        set_section_state(frm, 'reflections_section', true);
        set_field_state(frm, 'custom_self_assessment_on_annual_progress', true);
        set_field_state(frm, 'custom_upward_feedback_to_manager', true);
        set_field_state(frm, 'custom_annual_employee_performance_development_needs', true);
        set_field_state(frm, 'custom_annual_manager_feedback', true);
        set_field_state(frm, 'custom_rating_instructions', true);
        set_field_state(frm, 'custom_annual_manager_rating', true);
        set_tab_state('custom_technical__behavio', false);
    }

    // -----------------------------------------------------------------
    // 4. PHASE 3 (ANNUAL APPRAISAL) FIELD VISIBILITY
    // -----------------------------------------------------------------
    else if (is_phase_3) {
        // Show Mid-Term history as read-only reference
        set_field_state(
            frm, 
            'custom_midterm_employee_upward_feedback', 
            false, 
            1, 
            '<b>Mid Term Appraisal: Self-appraisal (Historical)</b>'
        );
        set_field_state(
            frm, 
            'custom_midterm_manager_feedback', 
            false, 
            1, 
            '<b>Mid Term Appraisal: Manager assessment/feedback (Historical)</b>'
        );

        // Hide empty standard reflections_section to avoid redundant empty box
        set_section_state(frm, 'reflections_section', true);
        set_field_state(
            frm, 
            'custom_self_assessment_on_annual_progress', 
            false, 
            can_edit_annual_self ? 0 : 1, 
            '<b>Annual Appraisal: Self-appraisal (Annual Progress)</b><br><span style="font-weight: normal; font-size: 12px; color: #687684;">Reflect on your achievements and areas of progress over the full annual cycle.</span>'
        );
        set_field_state(
            frm, 
            'custom_upward_feedback_to_manager', 
            false, 
            can_edit_annual_self ? 0 : 1, 
            '<b>Feedback to your manager</b><br><span style="font-weight: normal; font-size: 12px; color: #687684;">Feedback to your manager about how you feel you have been managed during the review period.</span>'
        );
        set_field_state(
            frm, 
            'custom_annual_employee_performance_development_needs', 
            false, 
            can_edit_dev_needs ? 0 : 1, 
            '<b>Performance Development Needs (Agreed with Manager)</b>'
        );

        // Place fields in chronological order in Self Appraisal tab
        move_field(frm, 'custom_midterm_employee_upward_feedback', 'custom_objectives__achievements', 'after');
        move_field(frm, 'custom_midterm_manager_feedback', 'custom_midterm_employee_upward_feedback', 'after');
        move_field(frm, 'custom_self_assessment_on_annual_progress', 'custom_midterm_manager_feedback', 'after');
        move_field(frm, 'custom_upward_feedback_to_manager', 'custom_self_assessment_on_annual_progress', 'after');
        move_field(frm, 'custom_annual_employee_performance_development_needs', 'custom_upward_feedback_to_manager', 'after');

        let ctx = get_user_role_context(frm);
        can_edit_mgr_ann = (ctx.is_line_manager || ctx.is_admin) && (state === 'Pending Manager Review');
        let show_comp_tab = false;
        let show_mgr_fb_tab = false;

        if (state === 'Completed') {
            show_mgr_fb_tab = true;
            // Competencies ONLY visible if NOT own appraisal and (line manager or admin)
            show_comp_tab = !ctx.is_actual_employee && (ctx.is_line_manager || ctx.is_admin);
        } else if (state === 'Pending Manager Review' && !ctx.is_actual_employee && (ctx.is_line_manager || ctx.is_admin)) {
            show_comp_tab = true;
            show_mgr_fb_tab = true;
        }

        set_tab_state('custom_technical__behavio', show_comp_tab, frm);
        if (show_comp_tab) {
            setup_competencies(frm);
        } else {
            set_field_state(frm, 'custom_behavioural_competencies', true, 1);
            set_field_state(frm, 'custom_executive_technical_competencies', true, 1);
            set_field_state(frm, 'custom_leadership_technical_competencies', true, 1);
        }
        set_tab_state('feedback_tab', show_mgr_fb_tab, frm);

        if (show_mgr_fb_tab) {
            set_field_state(
                frm, 
                'custom_annual_manager_feedback', 
                false, 
                can_edit_mgr_ann ? 0 : 1, 
                '<b>Annual Appraisal: Manager assessment/feedback</b>',
                can_edit_mgr_ann ? 1 : 0
            );
            set_field_state(frm, 'custom_rating_instructions', false);
            set_field_state(
                frm, 
                'custom_annual_manager_rating', 
                false, 
                can_edit_mgr_ann ? 0 : 1, 
                '<b>Annual Manager Rating</b>', 
                can_edit_mgr_ann ? 1 : 0
            );
            move_field(frm, 'custom_rating_instructions', 'custom_annual_manager_rating', 'before');
        } else {
            set_field_state(frm, 'custom_annual_manager_feedback', true, 1);
            set_field_state(frm, 'custom_rating_instructions', true, 1);
            set_field_state(frm, 'custom_annual_manager_rating', true, 1);
        }
        apply_css_tab_isolation(frm);
    }

    setTimeout(() => {
        let fields_to_resize = [
            'custom_self_assessment_on_annual_progress',
            'custom_upward_feedback_to_manager',
            'custom_midterm_employee_upward_feedback',
            'custom_midterm_manager_feedback',
            'custom_annual_manager_feedback',
            'custom_annual_employee_performance_development_needs'
        ];
        fields_to_resize.forEach(field => {
            if (frm.fields_dict[field] && frm.fields_dict[field].$input) {
                frm.fields_dict[field].$input.css({'min-height': '120px', 'height': '120px'});
            }
        });

        // Enforce DOM level locks on employee self-appraisal fields
        ['custom_self_assessment_on_annual_progress', 'custom_upward_feedback_to_manager', 'custom_midterm_employee_upward_feedback'].forEach(fn => {
            let f = frm.fields_dict[fn];
            let is_editable = (fn === 'custom_midterm_employee_upward_feedback') ? can_edit_midterm_self : can_edit_annual_self;
            if (f && f.$input) {
                if (!is_editable) {
                    f.$input.prop('readonly', true).css({
                        'background-color': '#f8fafc',
                        'border-color': '#e2e8f0',
                        'pointer-events': 'none',
                        'cursor': 'not-allowed',
                        'user-select': 'text'
                    });
                } else {
                    f.$input.prop('readonly', false).css({
                        'background-color': '#ffffff',
                        'border-color': '',
                        'pointer-events': 'auto',
                        'cursor': 'text',
                        'user-select': 'auto'
                    });
                }
            }
        });
    }, 250);
}

function lock_overview_tab(frm) {
    lock_and_clean_overview_tab(frm);
}

function render_progress_bar(frm) {
    let field = 'custom_status_dashboard';
    if (!frm.fields_dict[field]) return;

    let state = frm.doc.workflow_state || 'Pending';

    // Status evaluation for all items
    let obj_set_status = 'pending';
    let obj_rev_status = 'pending';
    let phase1_card = 'pending';

    let mid_prog_status = 'pending';
    let mid_self_status = 'pending';
    let mid_mgr_status = 'pending';
    let mid_comp_status = 'pending';
    let phase2_card = 'pending';

    let ann_prog_status = 'pending';
    let ann_self_status = 'pending';
    let ann_mgr_status = 'pending';
    let ann_comp_status = 'pending';
    let phase3_card = 'pending';

    let progress_pct = 15;
    let current_stage_badge = 'Objectives: Set Objectives';

    if (!frm.doc.workflow_state || state === 'Pending' || state === 'Draft') {
        obj_set_status = 'active';
        phase1_card = 'active';
        progress_pct = 15;
        current_stage_badge = 'Objectives: Set Objectives';
    } else if (state === 'Objectives Rejected') {
        obj_set_status = 'rejected';
        phase1_card = 'rejected';
        progress_pct = 15;
        current_stage_badge = 'Objectives: Rejected by Manager (Action Needed)';
    } else if (state === 'Objective Review Pending') {
        obj_set_status = 'completed';
        obj_rev_status = 'active';
        phase1_card = 'active';
        progress_pct = 25;
        current_stage_badge = 'Objectives: Review & Approval by Manager';
    } else if (state === 'Objectives Approved') {
        obj_set_status = 'completed';
        obj_rev_status = 'completed';
        phase1_card = 'completed';

        mid_prog_status = 'active';
        mid_self_status = 'active';
        phase2_card = 'active';
        progress_pct = 40;
        current_stage_badge = 'Mid Term: Progress & Self-Appraisal';
    } else if (state === 'Mid-Term Rejected') {
        obj_set_status = 'completed';
        obj_rev_status = 'completed';
        phase1_card = 'completed';

        mid_prog_status = 'rejected';
        mid_self_status = 'rejected';
        phase2_card = 'rejected';
        progress_pct = 40;
        current_stage_badge = 'Mid Term: Rejected by Manager (Action Needed)';
    } else if (state === 'Mid-Term Review Pending') {
        obj_set_status = 'completed';
        obj_rev_status = 'completed';
        phase1_card = 'completed';

        mid_prog_status = 'completed';
        mid_self_status = 'completed';
        mid_mgr_status = 'active';
        phase2_card = 'active';
        progress_pct = 55;
        current_stage_badge = 'Mid Term: Manager Assessment / Feedback';
    } else if (state === 'Mid-Term Completed') {
        obj_set_status = 'completed';
        obj_rev_status = 'completed';
        phase1_card = 'completed';

        mid_prog_status = 'completed';
        mid_self_status = 'completed';
        mid_mgr_status = 'completed';
        mid_comp_status = 'completed';
        phase2_card = 'completed';

        ann_prog_status = 'active';
        ann_self_status = 'active';
        phase3_card = 'active';
        progress_pct = 75;
        current_stage_badge = 'Annual: Progress & Self-Appraisal';
    } else if (state === 'Appraisal Rejected') {
        obj_set_status = 'completed';
        obj_rev_status = 'completed';
        phase1_card = 'completed';

        mid_prog_status = 'completed';
        mid_self_status = 'completed';
        mid_mgr_status = 'completed';
        mid_comp_status = 'completed';
        phase2_card = 'completed';

        ann_prog_status = 'rejected';
        ann_self_status = 'rejected';
        phase3_card = 'rejected';
        progress_pct = 75;
        current_stage_badge = 'Annual: Rejected by Manager (Action Needed)';
    } else if (state === 'Pending Manager Review') {
        obj_set_status = 'completed';
        obj_rev_status = 'completed';
        phase1_card = 'completed';

        mid_prog_status = 'completed';
        mid_self_status = 'completed';
        mid_mgr_status = 'completed';
        mid_comp_status = 'completed';
        phase2_card = 'completed';

        ann_prog_status = 'completed';
        ann_self_status = 'completed';
        ann_mgr_status = 'active';
        phase3_card = 'active';
        progress_pct = 90;
        current_stage_badge = 'Annual: Manager Assessment / Feedback';
    } else if (state === 'Completed') {
        obj_set_status = 'completed';
        obj_rev_status = 'completed';
        phase1_card = 'completed';

        mid_prog_status = 'completed';
        mid_self_status = 'completed';
        mid_mgr_status = 'completed';
        mid_comp_status = 'completed';
        phase2_card = 'completed';

        ann_prog_status = 'completed';
        ann_self_status = 'completed';
        ann_mgr_status = 'completed';
        ann_comp_status = 'completed';
        phase3_card = 'completed';
        progress_pct = 100;
        current_stage_badge = 'Appraisal Cycle Completed';
    }

    function render_item(label, status) {
        let icon_html = '';
        if (status === 'completed') {
            icon_html = '<span class="item-icon completed">✓</span>';
        } else if (status === 'active') {
            icon_html = '<span class="item-icon active">●</span>';
        } else if (status === 'rejected') {
            icon_html = '<span class="item-icon rejected">!</span>';
        } else {
            icon_html = '<span class="item-icon pending">○</span>';
        }
        return `
            <div class="phase-item ${status}">
                ${icon_html}
                <span class="item-label">${label}</span>
            </div>
        `;
    }

    let html = `
    <div class="appraisal-dashboard-container">
