            .phase-card.rejected .phase-badge {
                background: #dc2626;
            }
            .phase-title {
                font-size: 14px;
                font-weight: 700;
                color: #1e293b;
            }
            .phase-card.active .phase-title {
                color: #166534;
            }
            .phase-card.completed .phase-title {
                color: #16a34a;
            }
            .phase-card.rejected .phase-title {
                color: #b91c1c;
            }
            .phase-items {
                display: flex;
                flex-direction: column;
                gap: 8px;
            }
            .phase-item {
                display: flex;
                align-items: flex-start;
                font-size: 12px;
                line-height: 1.4;
                color: #64748b;
            }
            .phase-item.active {
                color: #15803d;
                font-weight: 700;
            }
            .phase-item.completed {
                color: #1e293b;
                font-weight: 500;
            }
            .phase-item.rejected {
                color: #b91c1c;
                font-weight: 700;
            }
            .item-icon {
                display: inline-flex;
                justify-content: center;
                align-items: center;
                width: 16px;
                height: 16px;
                font-size: 11px;
                margin-right: 8px;
                flex-shrink: 0;
                margin-top: 1px;
            }
            .item-icon.completed {
                color: #16a34a;
                font-weight: 800;
                font-size: 13px;
            }
            .item-icon.active {
                color: #16a34a;
                font-size: 10px;
            }
            .item-icon.rejected {
                color: #dc2626;
                font-weight: 800;
            }
            .item-icon.pending {
                color: #cbd5e1;
            }
            .item-label {
                flex: 1;
            }
        </style>

        <div class="progress-bar-header">
