function apply_manager_security_lock(frm) {
    if (!frm || !frm.doc) return;
    let ctx = get_user_role_context(frm);
    let state = frm.doc.workflow_state || 'Pending';

    // Employee permissions for self-appraisal:
    // Strictly restricted to actual employee only. Line Manager can NEVER edit self-appraisal fields.
    let can_edit_midterm_self = ctx.is_actual_employee && ['Objectives Approved', 'Mid-Term Rejected'].includes(state);
    let can_edit_annual_self = ctx.is_actual_employee && ['Mid-Term Completed', 'Appraisal Rejected'].includes(state);

    // Line Manager & Admin permissions for manager feedback
    let can_edit_midterm_mgr = (ctx.is_line_manager || (ctx.is_admin && !ctx.is_actual_employee)) && (state === 'Mid-Term Review Pending');
    let can_edit_annual_mgr = (ctx.is_line_manager || (ctx.is_admin && !ctx.is_actual_employee)) && (state === 'Pending Manager Review');
    let can_edit_dev_needs = can_edit_annual_self || can_edit_annual_mgr;

    // 1. Mid-Term Employee upward feedback
    set_field_state(frm, 'custom_midterm_employee_upward_feedback', undefined, can_edit_midterm_self ? 0 : 1);

    // 2. Mid-Term Manager feedback: editable and mandatory only during manager review
    set_field_state(frm, 'custom_midterm_manager_feedback', undefined, can_edit_midterm_mgr ? 0 : 1, undefined, can_edit_midterm_mgr ? 1 : 0);

    // 3. Annual Self-appraisal fields
    set_field_state(frm, 'custom_self_assessment_on_annual_progress', undefined, can_edit_annual_self ? 0 : 1);
    set_field_state(frm, 'custom_upward_feedback_to_manager', undefined, can_edit_annual_self ? 0 : 1);
    set_field_state(frm, 'custom_annual_employee_performance_development_needs', undefined, can_edit_dev_needs ? 0 : 1);
    set_field_state(frm, 'reflections', undefined, 0);

    // 4. Annual Manager Feedback & Rating:
    let show_ann_fb_rating = ['Pending Manager Review', 'Completed'].includes(state);
    set_field_state(frm, 'custom_annual_manager_feedback', !show_ann_fb_rating, can_edit_annual_mgr ? 0 : 1, undefined, can_edit_annual_mgr ? 1 : 0);
    set_field_state(frm, 'custom_annual_manager_rating', !show_ann_fb_rating, can_edit_annual_mgr ? 0 : 1, undefined, can_edit_annual_mgr ? 1 : 0);
    set_field_state(frm, 'custom_rating_instructions', !show_ann_fb_rating);

    // 5. DOM Level Lock for Employee Self-Appraisal fields:
    ['custom_self_assessment_on_annual_progress', 'custom_upward_feedback_to_manager', 'custom_midterm_employee_upward_feedback'].forEach(fn => {
        let f = frm.fields_dict[fn];
        let is_editable = (fn === 'custom_midterm_employee_upward_feedback') ? can_edit_midterm_self : can_edit_annual_self;
        if (f && f.$input) {
            if (!is_editable) {
                f.$input.prop('readonly', true).css({
                    'background-color': '#f8fafc',
                    'border-color': '#e2e8f0',
                    'pointer-events': 'none',
                    'cursor': 'not-allowed',
                    'user-select': 'text'
                });
            } else {
                f.$input.prop('readonly', false).css({
                    'background-color': '#ffffff',
                    'border-color': '',
                    'pointer-events': 'auto',
                    'cursor': 'text',
                    'user-select': 'auto'
                });
            }
        }
    });

    apply_css_tab_isolation(frm);
}

function set_competency_grid_permissions(frm) {
    let ctx = get_user_role_context(frm);
    let can_edit = (ctx.is_line_manager || ctx.is_admin) && (frm.doc.workflow_state === 'Pending Manager Review');
    let tables = ['custom_behavioural_competencies', 'custom_executive_technical_competencies', 'custom_leadership_technical_competencies'];

    tables.forEach(table => {
        set_field_state(frm, table, undefined, can_edit ? 0 : 1);
        if (frm.fields_dict[table] && frm.fields_dict[table].grid) {
            let grid = frm.fields_dict[table].grid;
            grid.update_docfield_property('competency_name', 'read_only', 1);
            grid.update_docfield_property('rating', 'read_only', 1);
            grid.update_docfield_property('annual_rating', 'read_only', can_edit ? 0 : 1);
            grid.update_docfield_property('annual_rating', 'options', '\nProficient\nAdvanced\nExpert\nNot Applicable');
            grid.cannot_add_rows = true;
            grid.cannot_delete_rows = true;
            if (grid.wrapper) {
                grid.wrapper.find('.grid-add-row').hide();
                grid.wrapper.find('.grid-remove-rows').hide();
            }
            grid.grid_rows.forEach(row => {
                if (row.grid_form) {
                    row.grid_form.set_df_property('annual_rating', 'read_only', can_edit ? 0 : 1);
                    row.grid_form.set_df_property('annual_rating', 'options', '\nProficient\nAdvanced\nExpert\nNot Applicable');
                    row.grid_form.set_df_property('competency_name', 'read_only', 1);
                    row.grid_form.set_df_property('rating', 'read_only', 1);
                    row.grid_form.refresh_field('annual_rating');
                }
            });
            grid.refresh();
        }
    });
}

function setup_competencies(frm) {
    if (!frm.doc.employee) return;
    let ctx = get_user_role_context(frm);
    let state = frm.doc.workflow_state || 'Pending';

    // Technical & Behavioural Competencies is ONLY visible to Line Manager/HR/Admin in 'Pending Manager Review' or 'Completed'.
    // Strictly HIDDEN from the employee at all times.
    // Technical & Behavioural Competencies:
    // Strictly HIDDEN from the employee at all times (including HR on their own appraisal).
    // ONLY visible to Line Manager or HR/Admin on OTHER employees' appraisals.
    let show_competencies = false;
    if (!ctx.is_actual_employee && (ctx.is_line_manager || ctx.is_admin) && ['Pending Manager Review', 'Completed'].includes(state)) {
        show_competencies = true;
    }

    set_tab_state('custom_technical__behavio', show_competencies, frm);

    if (!show_competencies) {
        set_field_state(frm, 'custom_behavioural_competencies', true, 1);
        set_field_state(frm, 'custom_executive_technical_competencies', true, 1);
        set_field_state(frm, 'custom_leadership_technical_competencies', true, 1);
        return; 
    }

    frappe.db.get_value('Employee', frm.doc.employee, 'grade').then(r => {
        let grade = r.message ? (r.message.grade || '') : '';
        let is_exec = grade.startsWith('E');
        let is_lead = !is_exec; // Default to leadership competencies if not executive

        let can_edit = (ctx.is_line_manager || ctx.is_admin) && (frm.doc.workflow_state === 'Pending Manager Review');
        set_field_state(frm, 'custom_behavioural_competencies', false, can_edit ? 0 : 1);
        set_field_state(frm, 'custom_executive_technical_competencies', !is_exec, can_edit ? 0 : 1);
        set_field_state(frm, 'custom_leadership_technical_competencies', !is_lead, can_edit ? 0 : 1);

        // Auto populate if tables are empty
        auto_populate_competencies(frm, is_exec, is_lead);

        setTimeout(() => {
            set_competency_grid_permissions(frm);
            apply_custom_hover_tooltips(frm); 
        }, 100);
    });
}

function auto_populate_competencies(frm, is_exec, is_lead) {
    let behav_list = ['Communication', 'Persuasion and Influencing', 'Working with People', 'Innovation', 'Strategic Thinking', 'Driving Results', 'Developing People', 'Analytical Ability', 'Planning And Organizing', 'Managing Change'];
    let exec_list = ['Task Execution', 'Support to Team and Coordination', 'Problem Solving', 'Supervision and Oversight', 'Information Management', 'Support Planning and Adaptability', 'Learning Orientation'];
    let lead_list = ['Program Design & Implementation', 'Health Systems Strengthening', 'Research & Data Management', 'Community Engagement and Mobilization', 'Partnerships & Stakeholder Management', 'Resource Mobilisation and Financial Management', 'Governance & Leadership', 'Advocacy & Policy Influence', 'Digital and Innovation Capacity'];

    let dirty = false;
    if (!frm.doc.custom_behavioural_competencies || frm.doc.custom_behavioural_competencies.length === 0) {
        behav_list.forEach(item => {
            let row = frm.add_child('custom_behavioural_competencies');
            row.competency_name = item;
            row.rating = ''; 
        });
        dirty = true;
    }

    if (is_exec && (!frm.doc.custom_executive_technical_competencies || frm.doc.custom_executive_technical_competencies.length === 0)) {
        exec_list.forEach(item => {
            let row = frm.add_child('custom_executive_technical_competencies');
            row.competency_name = item;
            row.rating = '';
        });
        dirty = true;
    }

    if (is_lead && (!frm.doc.custom_leadership_technical_competencies || frm.doc.custom_leadership_technical_competencies.length === 0)) {
        lead_list.forEach(item => {
            let row = frm.add_child('custom_leadership_technical_competencies');
            row.competency_name = item;
            row.rating = '';
        });
        dirty = true;
    }

    if (dirty) {
        if (frm.fields_dict.custom_behavioural_competencies) frm.refresh_field('custom_behavioural_competencies');
        if (frm.fields_dict.custom_executive_technical_competencies) frm.refresh_field('custom_executive_technical_competencies');
        if (frm.fields_dict.custom_leadership_technical_competencies) frm.refresh_field('custom_leadership_technical_competencies');
    }
}

