frappe.ui.form.on('Appraisal', {
    setup: function(frm) {
        if (frm.is_new()) {
            frappe.msgprint({
                title: __('Direct Creation Disabled'),
                indicator: 'orange',
                message: __('Appraisals cannot be created manually. Appraisals are automatically generated when added to an Appraisal Cycle.')
            });
            frappe.set_route('List', 'Appraisal');
            return;
        }
        // Exclude Completed cycles from the Appraisal Cycle dropdown
        frm.set_query("appraisal_cycle", function() {
            return {
                filters: {
                    status: ["!=", "Completed"]
                }
            };
        });
    },

    refresh: function(frm) {
        if (frm.is_new()) {
            frappe.set_route('List', 'Appraisal');
            return;
        }
        // Exclude Completed cycles from the Appraisal Cycle dropdown
        frm.set_query("appraisal_cycle", function() {
            return {
                filters: {
                    status: ["!=", "Completed"]
                }
            };
        });

        // Remove 'View Goals' button from top header
        frm.remove_custom_button(__('View Goals'));
        setTimeout(() => {
            frm.remove_custom_button(__('View Goals'));
        }, 100);

        const is_admin = (frappe.session.user === 'Administrator');

        // Hide 'Cancel' button from everyone except Administrator
        if (!is_admin) {
            frm.page.clear_secondary_action();
            frm.page.wrapper.find('.btn:contains("Cancel"), button:contains("Cancel")').hide();
            setTimeout(() => {
                frm.page.clear_secondary_action();
                frm.page.wrapper.find('.btn:contains("Cancel"), button:contains("Cancel")').hide();
            }, 120);

            frm.page.wrapper.find('.form-footer').hide(); 
            frm.page.wrapper.find('.timeline').hide();
            frm.page.wrapper.find('.new-timeline').hide();
            frm.page.wrapper.find('.form-dashboard').hide(); 

            if (!$('#hide-appraisal-timeline-css').length) {
                $('head').append(`
                    <style id="hide-appraisal-timeline-css">
                        .form-footer, .timeline, .new-timeline, .form-dashboard {
                            display: none !important;
                        }
                    </style>
                `);
            }
        } else {
            $('#hide-appraisal-timeline-css').remove();
            frm.page.wrapper.find('.form-footer').show();
            frm.page.wrapper.find('.timeline').show();
            frm.page.wrapper.find('.new-timeline').show();
        }

        // Check if the linked Appraisal Cycle is Completed
        if (frm.doc.appraisal_cycle) {
            frappe.db.get_value('Appraisal Cycle', frm.doc.appraisal_cycle, 'status')
                .then(r => {
                    if (r.message && r.message.status === 'Completed') {
                        frm.cycle_is_completed = true;
                        frm.set_read_only();
                        frm.disable_save();

                        if (frm.page && frm.page.clear_actions_menu) {
                            frm.page.clear_actions_menu();
                        }
                        if (frm.page && frm.page.actions_btn_group) {
                            frm.page.actions_btn_group.addClass('hide hidden-xl').hide();
                        }
                        if (frm.page && frm.page.actions && frm.page.actions.parent) {
                            frm.page.actions.parent().addClass('hide hidden-xl').hide();
                        }

                        show_cycle_closed_banner(frm);
                    }
                });
        }

        enforce_appraisal_stage_actions(frm);
    },

    validate: function(frm) {
        if (frm.cycle_is_completed) {
            frappe.msgprint({
                title: __('Appraisal Cycle Closed'),
                indicator: 'red',
                message: __('This appraisal cycle has been officially closed and completed by HR. Further changes or submissions are no longer accepted.')
            });
            frappe.validated = false;
        }
    },

    before_workflow_action: function(frm) {
        if (frm.cycle_is_completed) {
            frappe.msgprint({
                title: __('Appraisal Cycle Closed'),
                indicator: 'red',
                message: __('This appraisal cycle has been officially closed and completed by HR. Further changes or submissions are no longer accepted.')
            });
            return Promise.reject();
        }

        let action = frm.selected_workflow_action;
        if (!action) return Promise.resolve();

        let title = "";
        let message_html = "";
        let btn_label = __("Yes, Proceed");
        let indicator = "orange";

        // Employee Submissions
        if (["Submit Objectives", "Resubmit Objectives"].includes(action)) {
            title = __("Submit Objectives");
            indicator = "blue";
            btn_label = __("Yes, Submit");
            message_html = `<b>Do you really want to submit?</b><br><br>Please check your entries. Once submitted, you <b>cannot edit</b> your objectives in this stage.`;
        } else if (["Submit Mid-Term Review", "Resubmit Mid-Term Review"].includes(action)) {
            title = __("Submit Mid-Term Review");
            indicator = "blue";
            btn_label = __("Yes, Submit");
            message_html = `<b>Do you really want to submit?</b><br><br>Please check your entries. Once submitted, you <b>cannot edit</b> your mid-term review in this stage.`;
        } else if (["Submit Annual Appraisal", "Resubmit Appraisal"].includes(action)) {
            title = __("Submit Annual Appraisal");
            indicator = "blue";
            btn_label = __("Yes, Submit");
            message_html = `<b>Do you really want to submit?</b><br><br>Please check your entries. Once submitted, you <b>cannot edit</b> this form anymore.`;
        } 
        // Manager Approvals
        else if (["Approve Objectives"].includes(action)) {
            title = __("Approve Objectives");
            indicator = "green";
            btn_label = __("Yes, Approve");
            message_html = `<b>Do you really want to approve?</b><br><br>Once approved, these objectives will be locked and <b>cannot be changed</b>.`;
        } else if (["Approve Mid-Term"].includes(action)) {
            title = __("Approve Mid-Term");
            indicator = "green";
            btn_label = __("Yes, Approve");
            message_html = `<b>Do you really want to approve?</b><br><br>Once approved, your mid-term ratings will be locked and <b>cannot be changed</b>.`;
        } else if (["Finalize & Complete"].includes(action)) {
            title = __("Finalize Appraisal");
            indicator = "green";
            btn_label = __("Yes, Finalize");
            message_html = `<b>Do you really want to finalize?</b><br><br>Once finalized, this appraisal is permanently closed and <b>cannot be changed</b>.`;
        } 
        // Rejections
        else if (["Reject Objectives", "Reject Mid-Term", "Reject"].includes(action)) {
            title = __("Reject & Send Back");
            indicator = "red";
            btn_label = __("Yes, Send Back");
            message_html = `<b>Do you want to send this back?</b><br><br>This form will be returned to the employee for corrections.`;
        } else {
            return Promise.resolve();
        }

        frappe.dom.unfreeze();

        return new Promise((resolve, reject) => {
            let is_confirmed = false;
            let d = new frappe.ui.Dialog({
                title: title,
                indicator: indicator,
                primary_action_label: btn_label,
                primary_action: function() {
                    is_confirmed = true;
                    d.hide();
                    frappe.dom.freeze();
                    resolve();
                },
                secondary_action_label: __("Cancel"),
                secondary_action: function() {
                    d.hide();
                    frm.selected_workflow_action = null;
                    frappe.dom.unfreeze();
                    reject();
                }
            });

            d.onhide = function() {
                if (!is_confirmed) {
                    frm.selected_workflow_action = null;
                    frappe.dom.unfreeze();
                    reject();
                }
            };

            d.$body.append(`<div style="font-size: 14px; padding: 4px 0;">${message_html}</div>`);
            d.show();
        });
    }
});

function show_cycle_closed_banner(frm) {
