                <div>
                    <div style="font-weight: 600; font-size: 14.5px; color: #0f172a;">
                        Appraisal Cycle Closed
                    </div>
                    <div style="font-size: 13px; color: #475569; margin-top: 2px;">
                        This appraisal cycle has been officially closed and completed by HR. All reviews and submissions are now finalized, and no further changes or submissions can be made.
                    </div>
                </div>
            </div>
        </div>
    `;

