function enforce_appraisal_stage_actions(frm) {
    if (!frm.doc || frm.is_new() || frm.cycle_is_completed) return;

    const user = frappe.session.user;
    if (user === 'Administrator') return;

    const state = frm.doc.workflow_state || 'Pending';
    const emp_email = frm.doc.custom_employee_email || frm.doc.employee_email;
    const mgr_email = frm.doc.custom_line_manager_email || frm.doc.custom_manager_email;

    const is_employee = (user && emp_email && user === emp_email);
    const is_manager = (user && mgr_email && user === mgr_email);

    let can_action = false;
    if (['Pending', 'Objectives Rejected', 'Objectives Approved', 'Mid-Term Completed', 'Mid-Term Rejected', 'Appraisal Rejected'].includes(state)) {
        can_action = is_employee;
    } else if (['Objective Review Pending', 'Mid-Term Review Pending', 'Pending Manager Review'].includes(state)) {
        can_action = is_manager;
    }

    if (!can_action) {
        if (frm.page && frm.page.clear_actions_menu) {
            frm.page.clear_actions_menu();
        }
        if (frm.page && frm.page.actions_btn_group) {
            frm.page.actions_btn_group.addClass('hide hidden-xl').hide();
        }
        if (frm.page && frm.page.actions && frm.page.actions.parent) {
            frm.page.actions.parent().addClass('hide hidden-xl').hide();
        }
    }
}

frappe.ui.form.on('Appraisal Cycle', {
    onload: function(frm) {
        // Automatically populate all companies when creating a new cycle
        if (frm.is_new() && (!frm.doc.custom_applicable_companies || frm.doc.custom_applicable_companies.length === 0)) {
            frappe.db.get_list('Company', {
                fields: ['name'],
                limit: 100,
                order_by: 'name asc'
            }).then(companies => {
                if (companies && companies.length && (!frm.doc.custom_applicable_companies || frm.doc.custom_applicable_companies.length === 0)) {
                    companies.forEach(c => {
                        let row = frm.add_child('custom_applicable_companies');
                        row.company = c.name;
                    });
                    frm.refresh_field('custom_applicable_companies');
                    if (frm.doc.custom_applicable_companies.length) {
                        frm.set_value('company', frm.doc.custom_applicable_companies[0].company);
                    }
                }
            });
        }
    },

    refresh: function(frm) {
        // Inject CSS to permanently hide Connections & standard Stats, and style sortable headers
        inject_appraisal_cycle_css();

        // Hide standard single 'Company' field from the UI
        frm.set_df_property('company', 'hidden', 1);

        // Hide old filters: branch, department, designation, custom_grade
        frm.set_df_property('branch', 'hidden', 1);
        frm.set_df_property('department', 'hidden', 1);
        frm.set_df_property('designation', 'hidden', 1);
        frm.set_df_property('custom_grade', 'hidden', 1);

        // Dropdown queries for filters
        frm.set_query("custom_filter_company", function() {
            let comps = (frm.doc.custom_applicable_companies || [])
                .map(d => d.company)
                .filter(Boolean);
            if (comps.length) {
                return { filters: { name: ["in", comps] } };
            }
            return {};
        });

        frm.set_query("custom_filter_manager", function() {
            let filters = { status: "Active" };
            if (frm.doc.custom_filter_company) {
                filters.company = frm.doc.custom_filter_company;
            }
            return { filters: filters };
        });

        frm.set_query("custom_filter_employee", function() {
            let filters = { status: "Active" };
            if (frm.doc.custom_filter_company) {
                filters.company = frm.doc.custom_filter_company;
            }
            if (frm.doc.custom_filter_manager) {
                filters.reports_to = frm.doc.custom_filter_manager;
            }
            return { filters: filters };
        });

        // Remove 'View Goals' button from top
        frm.remove_custom_button(__('View Goals'));
        setTimeout(() => {
            frm.remove_custom_button(__('View Goals'));
        }, 150);

        // Completely hide the Connections section and standard Stats bullets
        hide_connections_and_standard_stats(frm);

        // Hide Comments & Activity timeline for employees / non-System Managers
        hide_comments_and_activity_for_employees(frm);

        // Render customized KPI colored cards
        render_custom_kpi_cards(frm);

        // Ensure all 4 columns (Employee, Manager, Company, Appraisal Status) are visible
        ensure_appraisees_grid_columns(frm);

        // Apply table filtering and make headers sortable
        setTimeout(() => {
            hide_comments_and_activity_for_employees(frm);
            ensure_appraisees_grid_columns(frm);
            apply_appraisees_filter(frm);
            make_appraisees_grid_sortable(frm);
        }, 300);

        // Status-based permissions: ONLY lock when status is Completed!
        if (frm.doc.status === 'Completed') {
            frm.set_read_only();
            frm.disable_save();
            frm.set_df_property('get_employees', 'hidden', 1);
            frm.set_df_property('appraisees', 'read_only', 1);
            frm.set_df_property('custom_applicable_companies', 'read_only', 1);
            frm.remove_custom_button(__('Mark as In Progress'));
            setTimeout(() => {
                frm.remove_custom_button(__('Mark as In Progress'));
            }, 100);
        } else {
            frm.set_df_property('get_employees', 'hidden', 0);
            frm.set_df_property('appraisees', 'read_only', 0);
            frm.set_df_property('custom_applicable_companies', 'read_only', 0);
        }

        // Multi-company management tools
        if (frm.doc.status !== 'Completed') {
            frm.add_custom_button(__('Add All Companies'), function() {
                frappe.db.get_list('Company', {
                    fields: ['name'],
                    limit: 100,
                    order_by: 'name asc'
                }).then(companies => {
                    let existing = (frm.doc.custom_applicable_companies || []).map(d => d.company);
                    let added = 0;
                    (companies || []).forEach(c => {
                        if (!existing.includes(c.name)) {
                            let row = frm.add_child('custom_applicable_companies');
                            row.company = c.name;
                            added++;
                        }
                    });
                    if (added > 0) {
                        frm.refresh_field('custom_applicable_companies');
                        if (frm.doc.custom_applicable_companies.length) {
                            frm.set_value('company', frm.doc.custom_applicable_companies[0].company);
                        }
                        frappe.show_alert({
                            message: __(`Added ${added} companies to the cycle`),
                            indicator: 'green'
                        });
                        frm.dirty();
                    } else {
                        frappe.show_alert({
                            message: __('All companies are already added'),
                            indicator: 'blue'
                        });
                    }
                });
            }, __('Manage Companies'));

            frm.add_custom_button(__('Clear Companies'), function() {
                frm.clear_table('custom_applicable_companies');
                frm.refresh_field('custom_applicable_companies');
                frm.dirty();
                frappe.show_alert({
                    message: __('Cleared companies list'),
                    indicator: 'orange'
                });
            }, __('Manage Companies'));
        }
    },

    // Live table filtering on change of filters
    custom_filter_company: function(frm) {
        apply_appraisees_filter(frm);
    },

    custom_filter_manager: function(frm) {
        apply_appraisees_filter(frm);
    },

    custom_filter_employee: function(frm) {
        apply_appraisees_filter(frm);
    },

    // Clear filters button
    custom_clear_filters: function(frm) {
        frm.set_value('custom_filter_company', '');
        frm.set_value('custom_filter_manager', '');
        frm.set_value('custom_filter_employee', '');
        frm.refresh_field('custom_filter_company');
        frm.refresh_field('custom_filter_manager');
        frm.refresh_field('custom_filter_employee');
        apply_appraisees_filter(frm);
        frappe.show_alert({
            message: __('Filters cleared'),
            indicator: 'blue'
        });
    },

    // When clicking Get Employees: fetch new employees from directory matching filters
    get_employees: function(frm) {
        frappe.call({
            method: "set_employees",
            doc: frm.doc,
            freeze: true,
            freeze_message: __("Fetching Employees..."),
            callback: function(r) {
                if (r.docs && r.docs.length) {
                    frm.doc.appraisees = r.docs[0].appraisees || [];
                }
                frm.refresh_field("appraisees");
                frm.dirty();
                setTimeout(() => {
                    apply_appraisees_filter(frm);
                    make_appraisees_grid_sortable(frm);
                    render_custom_kpi_cards(frm);
                }, 100);
            }
        });
    },

    validate: function(frm) {
        if (frm.doc.custom_applicable_companies && frm.doc.custom_applicable_companies.length > 0) {
            frm.set_value('company', frm.doc.custom_applicable_companies[0].company);
        }
    },

    complete_cycle: function(frm) {
        frappe.call({
            method: 'access_custom.overrides.appraisal_cycle.get_incomplete_appraisals',
            args: { cycle_name: frm.doc.name },
            freeze: true,
            freeze_message: __('Checking Appraisals...'),
            callback: function(r) {
                let incomplete = r.message || [];
                show_complete_cycle_dialog(frm, incomplete);
            }
        });
    }
});

function apply_appraisees_filter(frm) {
    let comp = frm.doc.custom_filter_company;
    let mgr = frm.doc.custom_filter_manager;
    let emp = frm.doc.custom_filter_employee;

    let grid = frm.fields_dict['appraisees']?.grid;
    if (!grid || !grid.grid_rows) return;

    let visible_count = 0;
    let total_count = grid.grid_rows.length;

    grid.grid_rows.forEach(row => {
        let d = row.doc;
        let match = true;

        if (comp && d.custom_company !== comp) {
            match = false;
        }
        if (mgr && d.custom_manager !== mgr) {
            match = false;
        }
        if (emp && d.employee !== emp) {
            match = false;
        }

        if (match) {
            $(row.row).show();
            visible_count++;
        } else {
            $(row.row).hide();
        }
    });

    // Remove any previous empty filter notice
    grid.wrapper.find('.no-filter-match-row').remove();

    // If filter is active and 0 rows match in this cycle: show clean blank state with a Clear button
    if (visible_count === 0 && (comp || mgr || emp) && total_count > 0) {
        let filter_name = comp || mgr || emp;
        let empty_msg = __("No employees in this appraisal cycle match '{0}'.", [filter_name]);
        grid.wrapper.find('.grid-body').append(`
            <div class="no-filter-match-row text-center text-muted p-4" style="font-size: 13.5px; background-color: #f8fafc; border: 1.5px dashed #cbd5e1; border-radius: 6px; margin: 12px 6px; color: #64748b;">
                <span style="font-size: 18px;">🔍</span> ${empty_msg}
                <div style="margin-top: 8px;">
                    <button type="button" class="btn btn-xs btn-default" onclick="cur_frm.trigger('custom_clear_filters')">
                        <span class="text-primary font-weight-bold">✕ ${__('Clear Filters')}</span>
                    </button>
                </div>
            </div>
        `);
    }
}

