function ensure_appraisees_grid_columns(frm) {
    if (!frm.fields_dict['appraisees'] || !frm.fields_dict['appraisees'].grid) return;
    let grid = frm.fields_dict['appraisees'].grid;

    // Check if Appraisal Status is missing from visible_columns
    let has_status = (grid.visible_columns || []).some(col => col[0] && col[0].fieldname === 'custom_appraisal_status');
    if (!has_status || (grid.visible_columns && grid.visible_columns.length < 4)) {
        // Reset visible_columns and force Frappe to recompute with our updated widths
        grid.visible_columns = [];
        grid.setup_visible_columns();
        grid.header_row && grid.header_row.refresh();
        grid.refresh();
    }
}

function make_appraisees_grid_sortable(frm) {
    if (!frm.fields_dict['appraisees'] || !frm.fields_dict['appraisees'].grid) return;

    let grid = frm.fields_dict['appraisees'].grid;
    let $header = grid.wrapper.find('.grid-heading-row .grid-row');
    if (!$header.length) return;

    const sortable_fields = ['employee', 'custom_manager', 'custom_company', 'custom_appraisal_status'];

    sortable_fields.forEach(fieldname => {
        let $col = $header.find(`.grid-static-col[data-fieldname="${fieldname}"]`);
        if (!$col.length) return;

        $col.attr('title', __('Click to sort by {0}', [fieldname.replace('custom_', '').replace('_', ' ')]));

        $col.off('click.sort_col').on('click.sort_col', function(e) {
            e.preventDefault();
            e.stopPropagation();

            let current_dir = $col.attr('data-sort-dir') || 'none';
            let new_dir = (current_dir === 'asc') ? 'desc' : 'asc';

            $header.find('.grid-static-col').removeAttr('data-sort-dir');
            $header.find('.grid-sort-arrow').remove();

            $col.attr('data-sort-dir', new_dir);
            let arrow_char = (new_dir === 'asc') ? '▲' : '▼';
            $col.append(`<span class="grid-sort-arrow">${arrow_char}</span>`);

            sort_appraisees_array(frm, fieldname, new_dir);
        });
    });
}

function sort_appraisees_array(frm, fieldname, direction) {
    if (!frm.doc.appraisees || frm.doc.appraisees.length <= 1) return;

    let mult = (direction === 'asc') ? 1 : -1;

    frm.doc.appraisees.sort((a, b) => {
        let val_a = '';
        let val_b = '';

        if (fieldname === 'employee') {
            val_a = (a.employee_name || a.employee || '').toString().toLowerCase();
            val_b = (b.employee_name || b.employee || '').toString().toLowerCase();
        } else if (fieldname === 'custom_manager') {
            val_a = (a.custom_manager || '').toString().toLowerCase();
            val_b = (b.custom_manager || '').toString().toLowerCase();
        } else if (fieldname === 'custom_company') {
            val_a = (a.custom_company || '').toString().toLowerCase();
            val_b = (b.custom_company || '').toString().toLowerCase();
        } else if (fieldname === 'custom_appraisal_status') {
            val_a = (a.custom_appraisal_status || '').toString().toLowerCase();
            val_b = (b.custom_appraisal_status || '').toString().toLowerCase();
        } else {
            val_a = (a[fieldname] || '').toString().toLowerCase();
            val_b = (b[fieldname] || '').toString().toLowerCase();
        }

        if (val_a < val_b) return -1 * mult;
        if (val_a > val_b) return 1 * mult;
        return 0;
    });

    frm.doc.appraisees.forEach((row, i) => {
        row.idx = i + 1;
    });

    frm.refresh_field('appraisees');

    setTimeout(() => {
        apply_appraisees_filter(frm);
        make_appraisees_grid_sortable(frm);
        let grid = frm.fields_dict['appraisees'].grid;
        let $col = grid.wrapper.find(`.grid-heading-row .grid-static-col[data-fieldname="${fieldname}"]`);
        if ($col.length) {
            $col.attr('data-sort-dir', direction);
            $col.find('.grid-sort-arrow').remove();
            let arrow_char = (direction === 'asc') ? '▲' : '▼';
            $col.append(`<span class="grid-sort-arrow">${arrow_char}</span>`);
        }
    }, 150);
}

