                    Are you sure you want to mark this cycle as <b>Completed</b>?
                </p>
                <p style="color: #475569;">
                    All appraisals under this cycle have been finalized. Once completed, this cycle will be closed and locked.
                </p>
            </div>
        `;
    } else {
        let rows_html = incomplete.map(a => `
            <tr>
                <td style="font-weight: 500;">
                    <a href="/app/appraisal/${a.name}" target="_blank" style="color: #2563eb; text-decoration: underline;">${a.name}</a>
                </td>
