            </tr>
        `).join('');

        body_html = `
            <div style="font-size: 13.5px; line-height: 1.5; color: #1e293b;">
                <p style="font-weight: 600; font-size: 14.5px; margin-bottom: 8px;">
                    Are you sure you want to mark this cycle as <b>Completed</b>?
                </p>
                <div style="background-color: #fffbeb; border-left: 4px solid #f59e0b; padding: 10px 12px; border-radius: 4px; color: #b45309; margin-bottom: 12px; font-size: 13px;">
                    <b>⚠️ Notice:</b> There are <b>${incomplete.length} appraisals</b> still in progress. Once completed, this cycle will be closed and locked immediately. Unfinished appraisals can no longer be edited or approved by employees or managers.
                </div>
                <div style="max-height: 200px; overflow-y: auto; border: 1px solid #e2e8f0; border-radius: 6px; margin-bottom: 8px;">
                    <table class="table table-bordered table-condensed" style="margin: 0; font-size: 12px;">
                        <thead>
                            <tr style="background-color: #f8fafc; color: #475569;">
                                <th>Appraisal ID</th>
                                <th>Employee</th>
                                <th>Company</th>
                                <th>Current Status</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${rows_html}
                        </tbody>
                    </table>
                </div>
            </div>
        `;
    }

    let d = new frappe.ui.Dialog({
        title: title,
        indicator: indicator,
        primary_action_label: __('Yes, Complete Cycle'),
        primary_action: function() {
            d.hide();
            frm.call({
                method: 'complete_cycle',
                doc: frm.doc,
                freeze: true,
                freeze_message: __('Completing Cycle...')
