        listview.page.clear_primary_action();
        hide_employee_name_filter(listview);
    },
    get_indicator(doc) {
        let state = doc.workflow_state || 'Pending';
        if (state === 'Pending') {
            return [__('Objectives Pending'), 'orange', 'workflow_state,=,Pending'];
        } else if (state === 'Objective Review Pending') {
            return [__('Objective Review Pending'), 'orange', 'workflow_state,=,Objective Review Pending'];
        } else if (state === 'Objectives Approved') {
            return [__('Objectives Approved'), 'blue', 'workflow_state,=,Objectives Approved'];
        } else if (state === 'Objectives Rejected') {
            return [__('Objectives Rejected'), 'red', 'workflow_state,=,Objectives Rejected'];
        } else if (state === 'Mid-Term Review Pending') {
            return [__('Mid-Term Review Pending'), 'orange', 'workflow_state,=,Mid-Term Review Pending'];
        } else if (state === 'Mid-Term Rejected') {
            return [__('Mid-Term Rejected'), 'red', 'workflow_state,=,Mid-Term Rejected'];
        } else if (state === 'Mid-Term Completed') {
            return [__('Mid-Term Completed'), 'blue', 'workflow_state,=,Mid-Term Completed'];
        } else if (state === 'Pending Manager Review') {
            return [__('Annual Review Pending'), 'orange', 'workflow_state,=,Pending Manager Review'];
        } else if (state === 'Appraisal Rejected') {
            return [__('Annual Rejected'), 'red', 'workflow_state,=,Appraisal Rejected'];
        } else if (state === 'Completed') {
            return [__('Completed'), 'green', 'workflow_state,=,Completed'];
        }
    }
};

