function setup_contract_upload(frm) {

    let field =
        frm.fields_dict["customer_document"];


    if (!field) {

        console.error(
            "Field 'customer_document' was not found."
        );

        return;
    }


    // ----------------------------------------------------------
    // Override normal Attach button
    // ----------------------------------------------------------

    field.on_attach_click = function() {

        // Build normal Frappe upload options
        this.set_upload_options();


        // ------------------------------------------------------
        // CONTRACT / MOU
        // ONLY PDF
        // ------------------------------------------------------

        this.upload_options.restrictions = {

            allowed_file_types: [
                ".pdf"
            ]
        };


        // ------------------------------------------------------
        // Uploader message
        // ------------------------------------------------------

        this.upload_options.upload_notes =
            "Only PDF (.pdf) files are allowed.";


        // ------------------------------------------------------
        // Open File Uploader
        // ------------------------------------------------------

        this.file_uploader =
            new frappe.ui.FileUploader(
                this.upload_options
            );
    };
}


