let _active_calc_source = null;

function update_increment_grid_columns(frm) {
    let grid = frm.fields_dict['custom_increment_history'] && frm.fields_dict['custom_increment_history'].grid;
    if (!grid) return;

    // Define the exact 8 columns with explicit widths fitting Frappe visible space
    const target_cols = [
        ['date_of_joining', 1],
        ['date_of_issue', 1],
        ['current_annual_salary', 1],
        ['currency', 1],
        ['increment_percentage', 1],
        ['custom_increment_by_amount', 1],
        ['actual_increment_percentage', 1],
        ['custom_total_arrears_amount', 1],
        ['revised_annual_salary', 1]
    ];

    grid.visible_columns = [];
    for (let item of target_cols) {
        let fieldname = item[0];
        let colsize = item[1];
        let df = grid.fields_map[fieldname] || frappe.meta.get_docfield('Employee Increment Record', fieldname);
        if (df) {
            df.in_list_view = 1;
            df.hidden = 0;
            df.colsize = colsize;
            df.columns = colsize;
            grid.visible_columns.push([df, colsize]);
        }
    }

    // Hide remaining fields from table grid so they don't push the columns out
    let other_fields = ['entity', 'custom_increment_effective_date', 'arrears_percentage', 'custom_arrears_period', 'increment_letter_document'];
    for (let fn of other_fields) {
        let df = grid.fields_map[fn];
        if (df) {
            df.in_list_view = 0;
        }
    }

    if (typeof grid.make_head === 'function') {
        try { grid.make_head(); } catch (e) {}
    }
    if (typeof grid.refresh === 'function') {
        try { grid.refresh(); } catch (e) {}
    }
}

function get_increment_eligibility(frm, row) {
    if (!frm.doc.date_of_joining || !row.date_of_issue) {
        return { eligible: true, type: 'standard', effective_date: row.date_of_issue };
    }

    let doj_obj = frappe.datetime.str_to_obj(frm.doc.date_of_joining);
    let issue_obj = frappe.datetime.str_to_obj(row.date_of_issue);

    if (!doj_obj || !issue_obj) {
        return { eligible: true, type: 'standard', effective_date: row.date_of_issue };
    }

    let doj_year = doj_obj.getFullYear();
    let issue_year = issue_obj.getFullYear();
    let doj_month = doj_obj.getMonth(); // 0 to 11
    let doj_day = doj_obj.getDate();

    let cutoff = new Date(doj_year, 5, 30, 23, 59, 59); // 1st July 23:59:59
    let joined_on_or_before_cutoff = (doj_obj <= cutoff);

    // Rule 1: Cannot receive increment in the same year of joining
    if (issue_year === doj_year) {
        let next_year = joined_on_or_before_cutoff ? (doj_year + 1) : (doj_year + 2);
        return {
            eligible: false,
            reason: 'same_year',
            doj_year: doj_year,
            issue_year: issue_year,
            next_eligible_year: next_year
        };
    }

    // Rule 2: In Year Y+1
    if (issue_year === doj_year + 1) {
        if (!joined_on_or_before_cutoff) {
            // Joined after 30th June -> Not eligible in Year Y+1
            return {
                eligible: false,
                reason: 'after_july_next_year',
                doj_year: doj_year,
                issue_year: issue_year,
                next_eligible_year: doj_year + 2
            };
        }

        // Category A: Joined on exactly Jan 1st -> Full Year Increment
        if (doj_month === 0 && doj_day === 1) {
            return {
                eligible: true,
                type: 'full_year',
                effective_date: `${issue_year}-01-01`
            };
        }

        // Category B: Joined between Jan 2 and June 30 -> Prorata Split Period
        let anniv_date = new Date(issue_year, doj_month, doj_day);
        return {
            eligible: true,
            type: 'prorata_split',
            anniv_obj: anniv_date,
            effective_date: frappe.datetime.obj_to_str(anniv_date),
            doj_month: doj_month,
            doj_day: doj_day,
            issue_year: issue_year
        };
    }

    // Rule 3: Joined after 30th June and increment in Year Y+2 (Arrears Case!)
    if (!joined_on_or_before_cutoff && issue_year === doj_year + 2) {
        let anniv_date = new Date(doj_year + 1, doj_month, doj_day);
        return {
            eligible: true,
            type: 'arrears',
            anniv_obj: anniv_date,
            effective_date: frappe.datetime.obj_to_str(anniv_date),
            doj_month: doj_month,
            doj_day: doj_day,
            doj_year: doj_year
        };
    }

    // Rule 4: Established employees or subsequent years -> Full Year
    return {
        eligible: true,
        type: 'standard_full_year',
        effective_date: `${issue_year}-01-01`
    };
}

function get_eligibility_error_message(frm, elig) {
    let doj_display = frappe.datetime.str_to_user(frm.doc.date_of_joining);
    if (elig.reason === 'same_year') {
        return __('Employee joined on <b>{0}</b> and is <b>not eligible</b> for increment in the joining year ({1}). Eligible for increment from <b>01-01-{2}</b>.', [doj_display, elig.doj_year, elig.next_eligible_year]);
    } else if (elig.reason === 'after_july_next_year') {
        return __('Employee joined on <b>{0}</b> (after 30th June {1}) and is <b>not eligible</b> for increment in {2}. Eligible for increment from <b>01-01-{3}</b> with retrospective arrears.', [doj_display, elig.doj_year, elig.issue_year, elig.next_eligible_year]);
    } else {
        return __('Employee joined on <b>{0}</b> and is <b>not eligible</b> for increment in {1}.', [doj_display, elig.issue_year]);
    }
}

function handle_increment_row_added(frm, cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);
    if (!row) return;

    let rows = frm.doc.custom_increment_history || [];
    let base_salary = 0;

    let prev_rows = rows.filter(r => r.name !== cdn);
    if (prev_rows.length > 0) {
        let prev = prev_rows[prev_rows.length - 1];
        base_salary = flt(prev.revised_annual_salary) || flt(prev.current_annual_salary) || flt(frm.doc.custom_annual_salary) || 0;
    } else {
        base_salary = flt(frm.doc.custom_annual_salary) || 0;
    }

    _active_calc_source = 'row_added';
    try {
        if (base_salary > 0) {
            frappe.model.set_value(cdt, cdn, 'current_annual_salary', base_salary);
        }
        if (frm.doc.salary_currency) {
            frappe.model.set_value(cdt, cdn, 'currency', frm.doc.salary_currency);
        }

        if (frm.doc.date_of_joining) {
            frappe.model.set_value(cdt, cdn, 'date_of_joining', frm.doc.date_of_joining);
        }
        frappe.model.set_value(cdt, cdn, 'custom_increment_by_amount', 0);
        frappe.model.set_value(cdt, cdn, 'increment_percentage', 0);
        frappe.model.set_value(cdt, cdn, 'actual_increment_percentage', 0);
        frappe.model.set_value(cdt, cdn, 'arrears_percentage', 0);
        frappe.model.set_value(cdt, cdn, 'custom_total_arrears_amount', 0);
        frappe.model.set_value(cdt, cdn, 'custom_arrears_period', '');
        frappe.model.set_value(cdt, cdn, 'revised_annual_salary', base_salary);

        if (frm.doc.date_of_joining) {
            let elig = get_increment_eligibility(frm, row);
            if (elig.effective_date) {
                frappe.model.set_value(cdt, cdn, 'custom_increment_effective_date', elig.effective_date);
            }
        }
    } finally {
        setTimeout(() => { _active_calc_source = null; }, 150);
    }

    refresh_increment_grid_row(frm, cdn);
    setTimeout(() => { refresh_increment_grid_row(frm, cdn); }, 50);
    setTimeout(() => { refresh_increment_grid_row(frm, cdn); frm.refresh_field('custom_increment_history'); }, 150);
}

function ensure_row_current_salary(frm, cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);
    if (!row) return;
    if (!flt(row.current_annual_salary)) {
        handle_increment_row_added(frm, cdt, cdn);
    }
}

function clear_increment_row(frm, cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);
    let current = row ? flt(row.current_annual_salary) : 0;
    _active_calc_source = 'clear';
    try {
        if (frm.doc.date_of_joining) {
            frappe.model.set_value(cdt, cdn, 'date_of_joining', frm.doc.date_of_joining);
        }
        frappe.model.set_value(cdt, cdn, 'custom_increment_by_amount', 0);
        frappe.model.set_value(cdt, cdn, 'increment_percentage', 0);
        frappe.model.set_value(cdt, cdn, 'actual_increment_percentage', 0);
        frappe.model.set_value(cdt, cdn, 'arrears_percentage', 0);
        frappe.model.set_value(cdt, cdn, 'custom_total_arrears_amount', 0);
        frappe.model.set_value(cdt, cdn, 'custom_arrears_period', '');
        frappe.model.set_value(cdt, cdn, 'revised_annual_salary', current);
    } finally {
        setTimeout(() => { _active_calc_source = null; }, 150);
    }
    update_parent_annual_salary_from_increments(frm);
    refresh_increment_grid_row(frm, cdn);
}

function format_currency_val(amt, curr) {
    try {
        return format_currency(amt, curr);
    } catch(e) {
        return (curr ? curr + ' ' : '') + flt(amt).toLocaleString();
    }
}

// CALCULATION A: Triggered when user enters Increment by Amount
function calc_from_amount(frm, cdt, cdn) {
    if (_active_calc_source) return;
    let row = frappe.get_doc(cdt, cdn);
    if (!row) return;

    let current = flt(row.current_annual_salary);
    let amount = flt(row.custom_increment_by_amount);

    if (current <= 0 || amount <= 0) {
        clear_increment_row(frm, cdt, cdn);
        return;
    }

    let pct = (amount / current) * 100.0;
    row.increment_percentage = flt(pct.toFixed(2));
    calc_from_percentage(frm, cdt, cdn);
}

// CALCULATION B: Triggered when user enters Increment Percentage
function calc_from_percentage(frm, cdt, cdn) {
    if (_active_calc_source) return;
    let row = frappe.get_doc(cdt, cdn);
    if (!row) return;

    if (row.date_of_issue && frm.doc.date_of_joining) {
        let elig = get_increment_eligibility(frm, row);
        if (!elig.eligible) {
            frappe.msgprint({
                title: __('Not Eligible for Increment'),
                indicator: 'red',
                message: get_eligibility_error_message(frm, elig)
            });
            clear_increment_row(frm, cdt, cdn);
            return;
        }
    }

    let current = flt(row.current_annual_salary);
    let entered_pct = flt(row.increment_percentage);

    if (current <= 0 || entered_pct <= 0) {
        clear_increment_row(frm, cdt, cdn);
        return;
    }

    let elig = get_increment_eligibility(frm, row);
    let curr_code = row.currency || frm.doc.salary_currency || '';

    _active_calc_source = 'percentage';
    try {
        if (elig.type === 'full_year' || elig.type === 'standard_full_year') {
            // Category A / Standard: Full Year Increment
            let new_annual = Math.round(current * (1 + entered_pct / 100.0));
            let net_inc = new_annual - current;

            if (frm.doc.date_of_joining) {
                frappe.model.set_value(cdt, cdn, 'date_of_joining', frm.doc.date_of_joining);
            }
            frappe.model.set_value(cdt, cdn, 'custom_increment_effective_date', elig.effective_date);
            frappe.model.set_value(cdt, cdn, 'custom_arrears_period', '');
            frappe.model.set_value(cdt, cdn, 'custom_total_arrears_amount', 0);
            frappe.model.set_value(cdt, cdn, 'custom_increment_by_amount', net_inc);
            frappe.model.set_value(cdt, cdn, 'increment_percentage', flt(entered_pct.toFixed(2)));
            frappe.model.set_value(cdt, cdn, 'actual_increment_percentage', flt(entered_pct.toFixed(2)));
            frappe.model.set_value(cdt, cdn, 'arrears_percentage', 0);
            frappe.model.set_value(cdt, cdn, 'revised_annual_salary', new_annual);

            frappe.show_alert({
                message: __('Full Year Increment Applied: Revised Annual {0}', [format_currency_val(new_annual, curr_code)]),
                indicator: 'green'
            }, 6);

        } else if (elig.type === 'prorata_split') {
            // Category B: Prorata Split Period (Jan 2 to July 1)
            let new_annual = current * (1 + entered_pct / 100.0);
            let m_idx = elig.doj_month; // 0 to 11
            let dd = elig.doj_day;

            // Period 1: Non-eligible (Jan 1 to day before anniversary)
            let eval_year = elig.issue_year || (elig.anniv_obj ? elig.anniv_obj.getFullYear() : (new Date()).getFullYear());
            let days_in_month = new Date(eval_year, m_idx + 1, 0).getDate();

            // Period 1: Non-eligible (Jan 1 to day before anniversary)
            let days_before = dd - 1;
            let sal_non_elig = (current / 12.0) * m_idx + (current / 12.0) * (days_before / days_in_month);

            // Period 2: Eligible (anniversary to Dec 31)
            let months_after = 12 - (m_idx + 1);
            let days_after = days_in_month - dd + 1;
            let sal_elig = (new_annual / 12.0) * months_after + (new_annual / 12.0) * (days_after / days_in_month);

            let net_new_salary = Math.round(sal_non_elig + sal_elig);
            let net_inc = net_new_salary - current;
            let effective_pct = flt(((net_inc / current) * 100.0).toFixed(2));

            if (frm.doc.date_of_joining) {
                frappe.model.set_value(cdt, cdn, 'date_of_joining', frm.doc.date_of_joining);
            }
            frappe.model.set_value(cdt, cdn, 'custom_increment_effective_date', elig.effective_date);
            frappe.model.set_value(cdt, cdn, 'custom_arrears_period', '');
            frappe.model.set_value(cdt, cdn, 'custom_total_arrears_amount', 0);
            frappe.model.set_value(cdt, cdn, 'custom_increment_by_amount', net_inc);
            frappe.model.set_value(cdt, cdn, 'increment_percentage', flt(entered_pct.toFixed(2)));
            frappe.model.set_value(cdt, cdn, 'actual_increment_percentage', effective_pct);
            frappe.model.set_value(cdt, cdn, 'arrears_percentage', 0);
            frappe.model.set_value(cdt, cdn, 'revised_annual_salary', net_new_salary);

            frappe.show_alert({
                message: __('Prorata Increment Applied (Eff: {0}%): Revised Annual {1} (Net Hike: {2})', [effective_pct, format_currency_val(net_new_salary, curr_code), format_currency_val(net_inc, curr_code)]),
                indicator: 'blue'
            }, 7);

        } else if (elig.type === 'arrears') {
            // Category C: Arrears Case (Joined after 30th June, evaluated at doj_year + 2)
            // DO NOT ADD ARREARS INTO revised_annual_salary!
            let new_annual = Math.round(current * (1 + entered_pct / 100.0));
            let net_inc = new_annual - current;
            let monthly_hike = net_inc / 12.0;

            let m_idx = elig.doj_month;
            let dd = elig.doj_day;
            let dy = elig.doj_year;

            let month_names = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
            let arrears_months = 0;
            let period_label = '';

            let arr_year = dy + 1;
            let days_in_month = new Date(arr_year, m_idx + 1, 0).getDate();
            let full_mos = 12 - (m_idx + 1);
            let rem_days = days_in_month - dd + 1;
            if (dd === 1) {
                arrears_months = 12 - m_idx;
                period_label = `${month_names[m_idx]} 1 – Dec 31, ${arr_year} (${arrears_months} Months)`;
            } else {
                arrears_months = full_mos + (rem_days / days_in_month);
                period_label = `${month_names[m_idx]} ${dd} – Dec 31, ${arr_year} (${full_mos} Mos & ${rem_days} Days)`;
            }

            let total_arrears = Math.round(monthly_hike * arrears_months);
            let arrears_pct = current > 0 ? flt(((total_arrears / current) * 100.0).toFixed(2)) : 0;

            if (frm.doc.date_of_joining) {
                frappe.model.set_value(cdt, cdn, 'date_of_joining', frm.doc.date_of_joining);
            }
            frappe.model.set_value(cdt, cdn, 'custom_increment_effective_date', elig.effective_date);
            frappe.model.set_value(cdt, cdn, 'custom_arrears_period', period_label);
            frappe.model.set_value(cdt, cdn, 'custom_total_arrears_amount', total_arrears);
            frappe.model.set_value(cdt, cdn, 'custom_increment_by_amount', net_inc);
            frappe.model.set_value(cdt, cdn, 'increment_percentage', flt(entered_pct.toFixed(2)));
            frappe.model.set_value(cdt, cdn, 'actual_increment_percentage', flt(entered_pct.toFixed(2)));
            frappe.model.set_value(cdt, cdn, 'arrears_percentage', arrears_pct);
            frappe.model.set_value(cdt, cdn, 'revised_annual_salary', new_annual);

            frappe.show_alert({
                message: __('Arrears Calculated: {0} ({1}). Revised Annual: {2}', [format_currency_val(total_arrears, curr_code), period_label, format_currency_val(new_annual, curr_code)]),
                indicator: 'green'
            }, 7);
        }
    } finally {
        setTimeout(() => { _active_calc_source = null; }, 150);
    }

    update_parent_annual_salary_from_increments(frm);
    refresh_increment_grid_row(frm, cdn);
}

function refresh_increment_grid_row(frm, cdn) {
    let grid = frm.fields_dict['custom_increment_history'] && frm.fields_dict['custom_increment_history'].grid;
    if (grid && grid.grid_rows_by_docname && grid.grid_rows_by_docname[cdn]) {
        let grid_row = grid.grid_rows_by_docname[cdn];
        grid_row.refresh_field('date_of_joining');
        grid_row.refresh_field('current_annual_salary');
        grid_row.refresh_field('custom_increment_by_amount');
        grid_row.refresh_field('increment_percentage');
        grid_row.refresh_field('actual_increment_percentage');
        grid_row.refresh_field('arrears_percentage');
        grid_row.refresh_field('custom_increment_effective_date');
        grid_row.refresh_field('custom_arrears_period');
        grid_row.refresh_field('custom_total_arrears_amount');
        grid_row.refresh_field('revised_annual_salary');
        if (frm.doc.salary_currency) {
            grid_row.refresh_field('currency');
        }
    }
}

function update_parent_annual_salary_from_increments(frm) {
    let rows = frm.doc.custom_increment_history || [];
    let latest_revised = 0;

    for (let i = rows.length - 1; i >= 0; i--) {
        if (flt(rows[i].revised_annual_salary) > 0) {
            latest_revised = flt(rows[i].revised_annual_salary);
            break;
        }
    }

    if (latest_revised > 0) {
        frm.set_value('custom_annual_salary', latest_revised);
        frm.refresh_field('custom_annual_salary');
    }
}

function sync_increment_joining_dates(frm) {
    if (!frm.doc.date_of_joining) return;
    let rows = frm.doc.custom_increment_history || [];
    let updated = false;
    rows.forEach(row => {
        if (!row.date_of_joining || row.date_of_joining !== frm.doc.date_of_joining) {
            row.date_of_joining = frm.doc.date_of_joining;
            updated = true;
        }
        // If row has revised_annual_salary and current_annual_salary, ensure actual_increment_percentage is populated
        let current = flt(row.current_annual_salary);
        let revised = flt(row.revised_annual_salary);
        if (current > 0 && revised > 0 && !flt(row.actual_increment_percentage)) {
            let eff = flt((((revised - current) / current) * 100.0).toFixed(2));
            row.actual_increment_percentage = eff;
            updated = true;
        }
        // If row has custom_total_arrears_amount, ensure arrears_percentage is populated
        let arrears = flt(row.custom_total_arrears_amount);
        if (current > 0 && arrears > 0 && !flt(row.arrears_percentage)) {
            let arr_pct = flt(((arrears / current) * 100.0).toFixed(2));
            row.arrears_percentage = arr_pct;
            updated = true;
        }
    });
    if (updated) {
        frm.refresh_field('custom_increment_history');
    }
}

