function enforce_increment_grid_columns(frm) {
    let field = frm.get_field('custom_increment_history');
    if (!field || !field.grid) return;
    let grid = field.grid;

    let target_fieldnames = [
        'date_of_joining',
        'date_of_issue',
        'current_annual_salary',
        'currency',
        'increment_percentage',
        'custom_increment_by_amount',
        'actual_increment_percentage',
        'custom_total_arrears_amount',
        'revised_annual_salary'
    ];

    function build_desired_visible_columns() {
        let cols = [];
        target_fieldnames.forEach(fn => {
            let df = (grid.docfields || []).find(d => d.fieldname === fn) ||
                     (frappe.meta.docfield_map && frappe.meta.docfield_map['Employee Increment Record'] && frappe.meta.docfield_map['Employee Increment Record'][fn]);
            if (df) {
                df.in_list_view = 1;
                df.columns = 1;
                df.colsize = 1;
                cols.push([df, 1]);
            }
        });
        return cols;
    }

    // Override setup_visible_columns so Frappe always uses our 8 columns in exact order
    grid.setup_visible_columns = function() {
        this.user_defined_columns = [];
        this.visible_columns = build_desired_visible_columns();
    };

    let current_cols = (grid.visible_columns || []).map(c => c[0] && c[0].fieldname);
    if (JSON.stringify(current_cols) !== JSON.stringify(target_fieldnames)) {
        grid.visible_columns = build_desired_visible_columns();
        try { grid.make_head(); } catch (e) {}
        try { grid.refresh(); } catch (e) {}
    }
}

