    },
    refresh: function(frm) {
        apply_increment_history_styles();
        enforce_increment_grid_columns(frm);
    }
});

frappe.ui.form.on('Employee Organization Association', {
    organization: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);
        if (!row.organization) return;

        let is_global = row.organization.toLowerCase().includes("global");
        if (is_global) {
            if (frm.doc.name && !frm.doc.name.startsWith("new-employee")) {
                frappe.model.set_value(cdt, cdn, "organization_employee_id", frm.doc.name);
            }
            return;
        }

        if (!row.organization_employee_id) {
            frappe.call({
                method: "get_next_sub_id",
                args: {
                    organization: row.organization
                },
                callback: function(r) {
                    if (r.message && r.message.sub_id) {
                        frappe.model.set_value(cdt, cdn, "organization_employee_id", r.message.sub_id);
                    }
                }
            });
        }
    },
    primary: function(frm, cdt, cdn) {
        let row = frappe.get_doc(cdt, cdn);
        if (!row.organization) return;

        let is_global = row.organization.toLowerCase().includes("global");
