if (!frappe.ui._employee_uploader_wrapped && frappe.ui.FileUploader) {
    frappe.ui._original_FileUploader = frappe.ui.FileUploader;

    frappe.ui.FileUploader = class EmployeeSafeFileUploader extends frappe.ui._original_FileUploader {
        constructor(opts = {}) {
            let is_employee = (cur_frm && cur_frm.doctype === 'Employee') || (opts && opts.doctype === 'Employee');
            let fieldname = opts && opts.fieldname;
            let rule = is_employee && fieldname ? ATTACHMENT_FIELD_RULES[fieldname] : null;

            if (rule) {
                opts.restrictions = opts.restrictions || {};
                opts.restrictions.allowed_file_types = rule.exts;

                // Intercept on_success callback to prevent auto-save if an invalid file passed through
                let orig_on_success = opts.on_success;
                opts.on_success = function(file) {
                    let fname = (file.file_url || file.file_name || file.name || '').toLowerCase();
                    let clean = fname.split('?')[0].split('#')[0].trim();
                    let valid = rule.exts.some(ext => clean.endsWith(ext));

                    if (!valid) {
                        if (file.name) {
                            frappe.call({
                                method: 'frappe.client.delete',
                                args: { doctype: 'File', name: file.name }
                            });
                        }
                        show_format_error_dialog(rule.label, rule.desc);
                        return false;
                    }

                    if (orig_on_success) {
                        return orig_on_success.apply(this, arguments);
                    }
                };
            }

            super(opts);

            // Hook add_files on the mounted Vue component to intercept invalid files at selection/drop
            if (rule && this.uploader) {
                let uploader_instance = this;
                let orig_add_files = this.uploader.add_files;
                this.uploader.add_files = function(files) {
                    let file_array = Array.from(files || []);
                    let invalid = file_array.find(f => {
                        let n = (f.name || '').toLowerCase().trim();
                        return !rule.exts.some(ext => n.endsWith(ext));
                    });

                    if (invalid) {
                        // Close the FileUploader dialog first so exactly ONE modal appears
                        if (uploader_instance.dialog) {
                            uploader_instance.dialog.hide();
                        }
                        // Open our persistent format dialog
                        setTimeout(() => {
                            show_format_error_dialog(rule.label, rule.desc);
                        }, 120);
                        return; // DO NOT add file to upload queue
                    }

                    return orig_add_files.apply(this, arguments);
                };
            }
        }
    };
    frappe.ui._employee_uploader_wrapped = true;
}

// ------------------------------------------------------------
// FIELD LEVEL HANDLERS & CLEANUP
// ------------------------------------------------------------
function handle_attach_field_change(frm, cdt, cdn, fieldname, rule) {
    let row = (cdt && cdn && locals[cdt]) ? locals[cdt][cdn] : frm.doc;
    if (!row) return;

    let val = row[fieldname];
    if (val && !is_valid_attachment(val, rule.exts)) {
        // Prevent form auto-save immediately
        frappe.validated = false;
        if (frm) {
            frm.save_disabled = true;
            if (frm.save_timer) clearTimeout(frm.save_timer);
            setTimeout(() => { if (frm) frm.save_disabled = false; }, 1500);
        }

        // Clear value immediately
        row[fieldname] = null;
        if (cdt && cdn) {
            frappe.model.set_value(cdt, cdn, fieldname, null);
        } else {
            frm.set_value(fieldname, null);
        }

        show_format_error_dialog(rule.label, rule.desc);
    }
}

