function validate_employee_age(frm) {
    if (!frm.doc.date_of_birth) return true;

    let dob_str = frm.doc.date_of_birth;
    let parts = dob_str.split('-');
    if (parts.length !== 3) return true;

    let dob = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
    let today = new Date();

    let age = today.getFullYear() - dob.getFullYear();
    let month_diff = today.getMonth() - dob.getMonth();
    if (month_diff < 0 || (month_diff === 0 && today.getDate() < dob.getDate())) {
        age--;
    }

    if (age < 18) {
        frappe.msgprint({
            title: __('Invalid Date of Birth'),
            indicator: 'red',
            message: __('The employee must be at least <b>18 years old</b>. Current calculated age: <b>{0} years</b>.', [age])
        });
        frm.set_value('date_of_birth', null);
        return false;
    }
    return true;
}

frappe.ui.form.on('Employee', {
