        update_phone_placeholders(frm);
    },
    validate: function(frm) {
        // Validation runs STRICTLY ONLY during saving (when clicking Save)

        // Clean trailing prefixes on non-mandatory fields if no subscriber digits
        if (is_phone_empty(frm.doc.emergency_phone_number)) {
            frm.doc.emergency_phone_number = '';
        }

        for (let row of (frm.doc.custom_referee_details_ || [])) {
            if (is_phone_empty(row.phone_no)) {
                row.phone_no = '';
            }
        }

        // 1. Personal Mobile (MANDATORY)
        if (is_phone_empty(frm.doc.cell_number)) {
