                indicator: 'red',
                message: __('<b>Personal Mobile</b> is mandatory. Please enter a valid mobile number.')
            });
            frappe.validated = false;
            return false;
        }

        let res1 = validate_phone_number_format(frm.doc.cell_number, get_emp_country(frm), 'Personal Mobile');
        if (!res1.valid) {
            frappe.msgprint({
                title: __('Invalid Phone Format'),
                indicator: 'red',
                message: res1.message
            });
            frappe.validated = false;
            return false;
        }

        // 2. Emergency Mobile (NOT MANDATORY - validate only if user entered actual number)
        if (!is_phone_empty(frm.doc.emergency_phone_number)) {
            let res2 = validate_phone_number_format(frm.doc.emergency_phone_number, get_emp_country(frm), 'Emergency Mobile');
            if (!res2.valid) {
                frappe.msgprint({
                    title: __('Invalid Phone Format'),
