                if (!res3.valid) {
                    frappe.msgprint({
                        title: __('Invalid Phone Format'),
                        indicator: 'red',
                        message: res3.message
                    });
                    frappe.validated = false;
                    return false;
                }
            }
        }
    }
});

function is_phone_empty(val) {
    if (!val) return true;
    let s = String(val).trim();
    if (!s) return true;
    let clean = s.replace(/[\s\-\(\)]/g, '');
    let prefixes = ['', '+', '+1', '+91', '+65', '+20', '+971', '00', '001', '0091', '0065', '0020', '00971'];
    return prefixes.indexOf(clean) !== -1;
}

function get_emp_country(frm) {
    let c = (frm.doc.custom_nationality || frm.doc.custom_country12 || frm.doc.custom_country_of_employment || '').toLowerCase().trim();
    if (c.includes('india')) return 'India';
    if (c.includes('united states') || c.includes('usa') || c === 'us') return 'USA';
    if (c.includes('singapore')) return 'Singapore';
    if (c.includes('egypt')) return 'Egypt';
    if (c.includes('emirates') || c.includes('uae') || c.includes('dubai')) return 'UAE';
    return null;
}

function update_phone_placeholders(frm) {
    let country = get_emp_country(frm);
    let placeholder_map = {
        'India': 'e.g. 9876543210 or +91 9876543210',
        'USA': 'e.g. (202) 555-0123 or +1 2025550123',
        'Singapore': 'e.g. 81234567 or +65 81234567',
        'Egypt': 'e.g. 01012345678 or +20 1012345678',
        'UAE': 'e.g. 0501234567 or +971 501234567'
    };
    let ph = placeholder_map[country] || 'e.g. 9876543210 or +91 9876543210';
    ['cell_number', 'emergency_phone_number'].forEach(function(fn) {
        let f = frm.get_field(fn);
        if (f && f.$input) f.$input.attr('placeholder', ph);
    });
}

function enforce_phone_restrictions(frm) {
    if (!frm || !frm.wrapper) return;

    frm.set_df_property('cell_number', 'length', 14);
    frm.set_df_property('emergency_phone_number', 'length', 14);

    ['cell_number', 'emergency_phone_number'].forEach(function(f) {
        let field = frm.get_field(f);
        if (field && field.$input) {
            field.$input.attr('maxlength', 14);
        }
    });

    update_phone_placeholders(frm);

    // Real-time clamping on input / paste
    $(frm.wrapper).off('input.phone_limit paste.phone_limit')
        .on('input.phone_limit paste.phone_limit', 'input[data-fieldname="cell_number"], input[data-fieldname="emergency_phone_number"], input[data-fieldname="phone_no"]', function(e) {
            $(this).attr('maxlength', 14);
            if (this.value && this.value.length > 14) {
                this.value = this.value.substring(0, 14);
            }
        });
}

function validate_phone_number_format(phone_raw, doc_country, label) {
    if (is_phone_empty(phone_raw)) return { valid: true };
    let raw = String(phone_raw).trim();

    if (raw.length > 14) {
        return {
            valid: false,
            message: `<b>${label}</b> cannot exceed 14 characters.`
        };
    }

    if (/[^0-9+\-\(\)\s]/.test(raw)) {
        return {
            valid: false,
            message: `<b>${label}</b> contains invalid characters. Only numbers, +, -, (), and spaces are allowed.`
        };
    }

    let clean = raw.replace(/[\s\-\(\)]/g, '');
    let has_plus = clean.startsWith('+');
    let digits = clean.replace(/^\+/, '');

    if (!digits || !/^\d+$/.test(digits)) {
        return {
            valid: false,
            message: `<b>${label}</b> must contain a valid number.`
        };
    }

    let country = null;
    if (clean.startsWith('+1') || clean.startsWith('001')) country = 'USA';
    else if (clean.startsWith('+91') || clean.startsWith('0091')) country = 'India';
    else if (clean.startsWith('+65') || clean.startsWith('0065')) country = 'Singapore';
    else if (clean.startsWith('+20') || clean.startsWith('0020')) country = 'Egypt';
    else if (clean.startsWith('+971') || clean.startsWith('00971')) country = 'UAE';
    else if (doc_country) country = doc_country;

    function check_india() {
        if (!has_plus && digits.length === 10 && /^[6-9]/.test(digits)) return true;
        if (!has_plus && (digits.length === 10 || digits.length === 11) && digits.startsWith('0')) return true;
        if ((has_plus && clean.startsWith('+91') && digits.length === 12 && /^[6-9]/.test(digits.substring(2))) ||
            (!has_plus && digits.startsWith('91') && digits.length === 12 && /^[6-9]/.test(digits.substring(2)))) return true;
        if ((has_plus && clean.startsWith('+91') && digits.length === 12) ||
            (!has_plus && digits.startsWith('91') && digits.length === 12)) return true;
        return false;
    }

    function check_usa() {
        if (!has_plus && digits.length === 10 && /^[2-9]/.test(digits)) return true;
        if ((has_plus && clean.startsWith('+1') && digits.length === 11 && /^[2-9]/.test(digits.substring(1))) ||
            (!has_plus && digits.startsWith('1') && digits.length === 11 && /^[2-9]/.test(digits.substring(1)))) return true;
        return false;
    }

    function check_singapore() {
        if (!has_plus && digits.length === 8 && /^[689]/.test(digits)) return true;
        if ((has_plus && clean.startsWith('+65') && digits.length === 10 && /^[689]/.test(digits.substring(2))) ||
            (!has_plus && digits.startsWith('65') && digits.length === 10 && /^[689]/.test(digits.substring(2)))) return true;
        return false;
    }

    function check_egypt() {
        if (!has_plus && digits.length === 11 && /^01[0125]/.test(digits)) return true;
        if (!has_plus && (digits.length === 9 || digits.length === 10) && digits.startsWith('0')) return true;
        if ((has_plus && clean.startsWith('+20') && digits.length === 12 && /^1[0125]/.test(digits.substring(2))) ||
            (!has_plus && digits.startsWith('20') && digits.length === 12 && /^1[0125]/.test(digits.substring(2)))) return true;
        if ((has_plus && clean.startsWith('+20') && (digits.length === 10 || digits.length === 11)) ||
            (!has_plus && digits.startsWith('20') && (digits.length === 10 || digits.length === 11))) return true;
        return false;
    }

    function check_uae() {
        if (!has_plus && digits.length === 10 && digits.startsWith('05')) return true;
        if (!has_plus && digits.length === 9 && digits.startsWith('04')) return true;
        if ((has_plus && clean.startsWith('+971') && digits.length === 12 && digits.substring(3).startsWith('5')) ||
            (!has_plus && digits.startsWith('971') && digits.length === 12 && digits.substring(3).startsWith('5'))) return true;
        if ((has_plus && clean.startsWith('+971') && digits.length === 11 && digits.substring(3).startsWith('4')) ||
            (!has_plus && digits.startsWith('971') && digits.length === 11 && digits.substring(3).startsWith('4'))) return true;
        return false;
    }

    if (country === 'India') {
        if (check_india()) return { valid: true };
        return {
            valid: false,
            message: `<b>${label}</b> format is invalid for <b>India (+91)</b>.<br>• <b>Mobile (Domestic):</b> 10 digits starting with 6, 7, 8, or 9 (e.g. <b>9876543210</b>)<br>• <b>Mobile (International):</b> <b>+91 9876543210</b> or <b>+919876543210</b><br>• <b>Landline:</b> <b>0AA XXXXXXXX</b> or <b>+91 AA XXXXXXXX</b>`
        };
    }

    if (country === 'USA') {
        if (check_usa()) return { valid: true };
        return {
            valid: false,
            message: `<b>${label}</b> format is invalid for <b>USA (+1)</b>.<br>• <b>Domestic:</b> 10 digits e.g. <b>(AAA) NXX-XXXX</b> (e.g. <b>(202) 555-0123</b> or <b>2025550123</b>)<br>• <b>International:</b> <b>+1 AAA NXX XXXX</b> (e.g. <b>+1 2025550123</b>)`
        };
    }

    if (country === 'Singapore') {
        if (check_singapore()) return { valid: true };
        return {
            valid: false,
            message: `<b>${label}</b> format is invalid for <b>Singapore (+65)</b>.<br>• <b>Domestic Mobile:</b> 8 digits starting with 8 or 9 (e.g. <b>81234567</b>)<br>• <b>Domestic Landline:</b> 8 digits starting with 6 (e.g. <b>61234567</b>)<br>• <b>International:</b> <b>+65 8XXX XXXX</b> or <b>+65 6XXX XXXX</b>`
        };
    }

    if (country === 'Egypt') {
        if (check_egypt()) return { valid: true };
        return {
            valid: false,
            message: `<b>${label}</b> format is invalid for <b>Egypt (+20)</b>.<br>• <b>Domestic Mobile:</b> 11 digits starting with 01 (e.g. <b>01012345678</b>)<br>• <b>Domestic Landline:</b> <b>0A XXXXXXX</b> (e.g. <b>02 2345678</b>)<br>• <b>International:</b> <b>+20 1X XXXXXXXX</b> or <b>+20 A XXXXXXX</b>`
        };
    }

    if (country === 'UAE') {
        if (check_uae()) return { valid: true };
        return {
            valid: false,
            message: `<b>${label}</b> format is invalid for <b>Dubai / UAE (+971)</b>.<br>• <b>Domestic Mobile:</b> <b>05X XXX XXXX</b> (e.g. <b>0501234567</b>)<br>• <b>Domestic Landline:</b> <b>04 XXX XXXX</b> (e.g. <b>041234567</b>)<br>• <b>International:</b> <b>+971 5X XXX XXXX</b> or <b>+971 4 XXX XXXX</b>`
        };
    }

    if (check_india() || check_usa() || check_singapore() || check_egypt() || check_uae()) {
        return { valid: true };
    }

    return {
        valid: false,
        message: `<b>${label}</b> format is not recognized. Please use an allowed phone format for:<br>• <b>India (+91):</b> Domestic 10-digit mobile (e.g. <b>9876543210</b>) or <b>+91 9876543210</b><br>• <b>USA (+1):</b> 10-digit number (e.g. <b>(202) 555-0123</b> or <b>+1 2025550123</b>)<br>• <b>Singapore (+65):</b> 8 digits (e.g. <b>81234567</b> or <b>+65 81234567</b>)<br>• <b>Egypt (+20):</b> 11 digits starting with 01 (e.g. <b>01012345678</b>)<br>• <b>Dubai / UAE (+971):</b> <b>05X / 04</b> (e.g. <b>0501234567</b> or <b>+971 501234567</b>)<br><i>Maximum 14 characters allowed.</i>`
    };
}

// Global cache for Employee Name lookup in List View
window._employee_name_cache = window._employee_name_cache || {};

function load_employee_names(listview) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Employee",
            fields: ["name", "employee_name"],
            limit_page_length: 500
        },
        callback: function(r) {
            if (r.message) {
                let updated = false;
                r.message.forEach(emp => {
                    if (emp.name && emp.employee_name && window._employee_name_cache[emp.name] !== emp.employee_name) {
                        window._employee_name_cache[emp.name] = emp.employee_name;
                        updated = true;
                    }
                });
                // Update DOM elements for Line Manager column directly
                if (listview && listview.$result) {
                    listview.$result.find('.list-col-reports_to .employee-manager-name-text').each(function() {
                        let id = $(this).attr('data-reports-to');
                        if (id && window._employee_name_cache[id]) {
                            $(this).text(window._employee_name_cache[id]);
                            $(this).attr('title', window._employee_name_cache[id]);
                        }
                    });
                }
            }
        }
    });
}

