frappe.ui.form.on('Employee', {
    refresh: function(frm) {
        update_passport_field_hint(frm);
    },
    custom_nationality: function(frm) {
        update_passport_field_hint(frm);
    },
    place_of_issue: function(frm) {
        update_passport_field_hint(frm);
    },
    validate: function(frm) {
        // 1. Validate Passport Expiry > Date of Issue
        if (frm.doc.date_of_issue && frm.doc.valid_upto) {
            let issue_dt = frappe.datetime.str_to_obj(frm.doc.date_of_issue);
            let expiry_dt = frappe.datetime.str_to_obj(frm.doc.valid_upto);
            if (expiry_dt <= issue_dt) {
                frappe.msgprint({
                    title: __('Invalid Passport Dates'),
                    indicator: 'red',
                    message: __('<b>Passport Expiry</b> date must be greater than <b>Date of Issue</b>.')
                });
                frappe.validated = false;
                return false;
            }
        }

        // 2. Validate Passport Number format
        if (!frm.doc.passport_number) return;

        let passport = frm.doc.passport_number.trim();

        // Check for spaces or hyphens
        if (/\s/.test(passport) || /-/.test(passport)) {
            frappe.msgprint({
                title: __('Invalid Passport Number'),
                indicator: 'red',
                message: __('<b>Passport Number</b> must not contain spaces or hyphens. Please enter only alphanumeric characters.')
            });
            frappe.validated = false;
            return false;
        }

        // Check for case-sensitivity (must be capital letters)
        if (/[a-z]/.test(passport)) {
            frappe.msgprint({
                title: __('Invalid Passport Number'),
                indicator: 'red',
                message: __('<b>Passport numbers are case-sensitive</b> and must be entered using <b>UPPERCASE</b> capital letters.')
            });
            frappe.validated = false;
            return false;
        }

        // Determine country
        let country = get_passport_country(frm);

        if (country === 'United States') {
            let us_regex1 = /^[A-Z][0-9]{8}$/;
            let us_regex_legacy = /^[0-9]{9}$/;
            if (!us_regex1.test(passport) && !us_regex_legacy.test(passport)) {
                frappe.msgprint({
                    title: __('Invalid US Passport Number'),
                    indicator: 'red',
                    message: __('<b>Passport Number for United States</b> must be <b>1 capital letter followed by 8 numbers</b> (e.g., <b>A12345678</b>) or legacy 9 digits without spaces or hyphens.')
                });
                frappe.validated = false;
                return false;
            }
        } else if (country === 'India') {
            let in_regex1 = /^[A-Z][0-9]{7}$/;
            let in_regex_e = /^[A-Z]{2}[0-9]{6}$/;
            if (!in_regex1.test(passport) && !in_regex_e.test(passport)) {
                frappe.msgprint({
                    title: __('Invalid Indian Passport Number'),
                    indicator: 'red',
                    message: __('<b>Passport Number for India</b> must be <b>1 capital letter followed by 7 digits</b> (e.g., <b>Z1234567</b>) or <b>2 capital letters followed by 6 digits</b> without spaces or hyphens.')
                });
                frappe.validated = false;
                return false;
            }
        } else if (country === 'Singapore') {
            let sg_regex = /^[EK][0-9]{7}[A-Z]$/;
            if (!sg_regex.test(passport)) {
                frappe.msgprint({
                    title: __('Invalid Singapore Passport Number'),
                    indicator: 'red',
                    message: __('<b>Passport Number for Singapore</b> must be <b>9 alphanumeric characters</b> starting with <b>E</b> or <b>K</b>, followed by 7 digits, and ending with a letter (e.g., <b>E1234567A</b>).')
                });
                frappe.validated = false;
                return false;
            }
        } else if (country === 'Egypt') {
            let eg_regex = /^[A-Z][0-9]{8}$/;
            if (!eg_regex.test(passport)) {
                frappe.msgprint({
                    title: __('Invalid Egypt Passport Number'),
                    indicator: 'red',
                    message: __('<b>Passport Number for Egypt</b> must be <b>1 capital letter followed by 8 digits</b> (e.g., <b>A12345678</b>) without spaces or hyphens.')
                });
                frappe.validated = false;
                return false;
            }
        } else if (country === 'UAE') {
            let uae_regex = /^[0-9CFGHJKLMNPRTVWXYZ]{9}$/;
            if (!uae_regex.test(passport)) {
                frappe.msgprint({
                    title: __('Invalid UAE Passport Number'),
                    indicator: 'red',
                    message: __('<b>Passport Number for UAE (Dubai)</b> must be <b>9 alphanumeric characters</b> using numbers 0–9 and allowed letters (C, F, G, H, J, K, L, M, N, P, R, T, V, W, X, Y, Z), e.g., <b>C12345678</b>.')
                });
                frappe.validated = false;
                return false;
            }
        } else {
            let any_valid = (
                /^[A-Z][0-9]{7}$/.test(passport) ||
                /^[A-Z]{2}[0-9]{6}$/.test(passport) ||
                /^[A-Z][0-9]{8}$/.test(passport) ||
                /^[0-9]{9}$/.test(passport) ||
                /^[EK][0-9]{7}[A-Z]$/.test(passport) ||
                /^[0-9CFGHJKLMNPRTVWXYZ]{9}$/.test(passport)
            );

            if (!any_valid) {
                frappe.msgprint({
                    title: __('Invalid Passport Number Format'),
                    indicator: 'red',
                    message: __('<b>Passport Number</b> is invalid. All passport numbers are case-sensitive and must be entered without spaces or hyphens.<br><br><b>Supported formats:</b><br>• <b>India:</b> 1 capital letter + 7 digits (e.g., <b>Z1234567</b>)<br>• <b>United States / Egypt:</b> 1 letter + 8 digits (e.g., <b>A12345678</b>)<br>• <b>Singapore:</b> Starts with E or K, 7 digits, ends with letter (e.g., <b>E1234567A</b>)<br>• <b>UAE (Dubai):</b> 9 alphanumeric chars with allowed letters (e.g., <b>C12345678</b>)')
                });
                frappe.validated = false;
                return false;
            }
        }
    }
});

function get_passport_country(frm) {
    let country = (frm.doc.custom_nationality || '').trim().toLowerCase();
    if (!country && frm.doc.place_of_issue) {
        country = (frm.doc.place_of_issue || '').trim().toLowerCase();
    }
    if (!country && frm.doc.custom_country12) {
        country = (frm.doc.custom_country12 || '').trim().toLowerCase();
    }
    if (!country && frm.doc.custom_country_of_employment) {
        country = (frm.doc.custom_country_of_employment || '').trim().toLowerCase();
    }

    if (country.includes('india')) return 'India';
    if (country.includes('united states') || country.includes('usa') || country === 'us') return 'United States';
    if (country.includes('singapore')) return 'Singapore';
    if (country.includes('egypt')) return 'Egypt';
    if (country.includes('emirates') || country.includes('uae') || country.includes('dubai')) return 'UAE';

    return null;
}

function update_passport_field_hint(frm) {
    let field = frm.get_field('passport_number');
    if (!field || !field.$input) return;

    let country = get_passport_country(frm);
    let placeholder_map = {
        'United States': 'e.g. A12345678',
        'India': 'e.g. Z1234567',
        'Singapore': 'e.g. E1234567A',
        'Egypt': 'e.g. A12345678',
        'UAE': 'e.g. C12345678'
    };

    let placeholder = placeholder_map[country] || 'e.g. Z1234567 / A12345678';
    field.$input.attr('placeholder', placeholder);
}

frappe.ui.form.on('Employee', {
    onload_post_render: function(frm) {
        setup_pincode_helpers(frm);
    },
    refresh: function(frm) {
        setup_pincode_helpers(frm);
    },
    custom_country12: function(frm) {
        setup_pincode_helpers(frm);
    },
    custom_country1: function(frm) {
        setup_pincode_helpers(frm);
    },
    custom_pin_code: function(frm) {
        check_pincode_field_input(frm, 'custom_pin_code', 'custom_country12', 'Current Address');
    },
    custom_pin1: function(frm) {
        check_pincode_field_input(frm, 'custom_pin1', 'custom_country1', 'Permanent Address');
    },
    validate: function(frm) {
        // 1. Validate Current Address Pin Code (only if filled)
        if (!validate_address_pin(frm, 'custom_country12', 'custom_pin_code', 'Current Address')) {
            return false;
        }

        // 2. Validate Permanent Address Pin Code (only if filled)
        if (!validate_address_pin(frm, 'custom_country1', 'custom_pin1', 'Permanent Address')) {
            return false;
        }
    }
});

function setup_pincode_helpers(frm) {
    let pin_fields = [
        { pin: 'custom_pin_code', country: 'custom_country12', label: 'Current Address' },
        { pin: 'custom_pin1', country: 'custom_country1', label: 'Permanent Address' }
    ];

    pin_fields.forEach(function(item) {
        let field = frm.get_field(item.pin);
        if (!field) return;

        let country = (frm.doc[item.country] || '').toLowerCase().trim();

        field.format_for_input = function(val) {
            if (!val || val === 0 || val === '0') return '';
            return val;
        };

        if (field.$input) {
            let cur_val = field.$input.val();
            let doc_val = frm.doc[item.pin];
            if (cur_val === '0' || cur_val === 0 || !doc_val || doc_val === 0 || doc_val === '0') {
                field.$input.val('');
            }

            field.$input.off('blur.pincode_zero').on('blur.pincode_zero', function() {
                if (this.value === '0' || !this.value) {
                    this.value = '';
                }
            });

            if (country.includes('india')) {
                field.$input.attr('maxlength', 6);
                field.$input.attr('placeholder', 'e.g. 500081');
            } else {
                field.$input.removeAttr('maxlength');
                field.$input.attr('placeholder', '');
            }
        }
    });
}

function check_pincode_field_input(frm, pin_fieldname, country_fieldname, label) {
    let country = (frm.doc[country_fieldname] || '').toLowerCase().trim();
    if (!country.includes('india')) return;

    let field = frm.get_field(pin_fieldname);
    let raw_val = (field && field.$input ? field.$input.val() : '') || frm.doc[pin_fieldname] || '';
    raw_val = String(raw_val).trim();

    // If empty or 0, do nothing (it is optional)
    if (!raw_val || raw_val === '0') {
        if (field && field.$input) field.$input.val('');
        return;
    }

    // Only validate if a value is typed in
    if (/[^0-9]/.test(raw_val)) {
        frappe.msgprint({
            title: __('Invalid Pin Code'),
            indicator: 'red',
            message: __('<b>{0} Pin Code</b> must contain numbers only. Alphabets and special characters are not allowed.', [label])
        });
        return;
    }

    if (raw_val.length !== 6 || raw_val.startsWith('0')) {
        frappe.msgprint({
            title: __('Invalid Pin Code'),
            indicator: 'red',
            message: __('<b>{0} Pin Code</b> must be exactly <b>6 digits</b> only (e.g., <b>500081</b>) when Country is India.', [label])
        });
    }
}

function validate_address_pin(frm, country_fieldname, pin_fieldname, label) {
    let country = (frm.doc[country_fieldname] || '').toLowerCase().trim();
    if (!country.includes('india')) {
        return true;
    }

    let field = frm.get_field(pin_fieldname);
    let raw_val = (field && field.$input ? field.$input.val() : '') || '';
    raw_val = raw_val.trim();

    let doc_val = frm.doc[pin_fieldname];
    let doc_str = (doc_val !== null && doc_val !== undefined && doc_val !== 0) ? String(doc_val).trim() : '';

    let pin_to_check = raw_val || doc_str;

    // PIN CODE IS OPTIONAL: If empty, null, or 0, allow saving without any error!
    if (!pin_to_check || pin_to_check === '0') {
        return true;
    }

    // ONLY IF PIN CODE IS FILLED: check if it is valid
    if (/[^0-9]/.test(pin_to_check)) {
        frappe.msgprint({
            title: __('Invalid Pin Code'),
            indicator: 'red',
            message: __('<b>{0} Pin Code</b> must not contain alphabets or special characters. Only digits (0-9) are allowed.', [label])
        });
        frappe.validated = false;
        return false;
    }

    if (pin_to_check.length !== 6) {
        frappe.msgprint({
            title: __('Invalid Pin Code'),
            indicator: 'red',
            message: __('<b>{0} Pin Code</b> must be exactly <b>6 digits</b> only (e.g., <b>500081</b>). Current value has ' + pin_to_check.length + ' digits.', [label])
        });
        frappe.validated = false;
        return false;
    }

    if (pin_to_check.startsWith('0')) {
        frappe.msgprint({
            title: __('Invalid Pin Code'),
            indicator: 'red',
            message: __('<b>{0} Pin Code</b> cannot start with 0. Indian PIN codes are 6 digits starting from 1 to 9 (e.g., <b>500081</b>).', [label])
        });
        frappe.validated = false;
        return false;
    }

    return true;
}

