function validate_email_field(val, label) {
    if (!val || !String(val).trim()) return true;

    let raw = String(val).trim();

    // 1. Mandatory '@' and '.'
    if (raw.indexOf('@') === -1 || raw.indexOf('.') === -1) {
        frappe.msgprint({
            title: __('Invalid Email Address'),
            indicator: 'red',
            message: `<b>${label}</b> must contain both '<b>@</b>' and '<b>.</b>' (e.g. <b>name@example.com</b>).`
        });
        frappe.validated = false;
        return false;
    }

    // 2. Exactly one '@'
    let at_count = (raw.match(/@/g) || []).length;
    if (at_count !== 1) {
        frappe.msgprint({
            title: __('Invalid Email Address'),
            indicator: 'red',
            message: `<b>${label}</b> can only contain a single '<b>@</b>' symbol.`
        });
        frappe.validated = false;
        return false;
    }

    // 3. Only letters, numbers, '@', and '.' allowed
    if (/[^a-zA-Z0-9@.]/.test(raw)) {
        let invalid_matches = raw.match(/[^a-zA-Z0-9@.]/g) || [];
        let unique_invalids = [...new Set(invalid_matches)].map(c => `<b>${frappe.utils.escape_html(c)}</b>`).join(', ');
        frappe.msgprint({
            title: __('Invalid Email Address'),
            indicator: 'red',
            message: `<b>${label}</b> contains disallowed characters: ${unique_invalids}.<br><br><i>Only letters (a–z), numbers (0–9), '<b>@</b>', and dot ('<b>.</b>') are allowed. No other special characters are permitted.</i>`
        });
        frappe.validated = false;
        return false;
    }

    // 4. Structure check: local@domain.tld
    let parts = raw.split('@');
    let local_part = parts[0];
    let domain_part = parts[1];

    if (!local_part) {
        frappe.msgprint({
            title: __('Invalid Email Address'),
            indicator: 'red',
            message: `<b>${label}</b> is missing a username before '<b>@</b>'.`
        });
        frappe.validated = false;
        return false;
    }

    if (!domain_part) {
        frappe.msgprint({
            title: __('Invalid Email Address'),
            indicator: 'red',
            message: `<b>${label}</b> is missing a domain name after '<b>@</b>'.`
        });
        frappe.validated = false;
        return false;
    }

    if (domain_part.indexOf('.') === -1) {
        frappe.msgprint({
            title: __('Invalid Email Address'),
            indicator: 'red',
            message: `<b>${label}</b> domain must contain a dot (e.g. <b>gmail.com</b>).`
        });
        frappe.validated = false;
        return false;
    }

    if (domain_part.startsWith('.') || domain_part.endsWith('.')) {
        frappe.msgprint({
            title: __('Invalid Email Address'),
            indicator: 'red',
            message: `<b>${label}</b> domain cannot start or end with a dot.`
        });
        frappe.validated = false;
        return false;
    }

    if (local_part.startsWith('.') || local_part.endsWith('.')) {
        frappe.msgprint({
            title: __('Invalid Email Address'),
            indicator: 'red',
            message: `<b>${label}</b> username cannot start or end with a dot.`
        });
        frappe.validated = false;
        return false;
    }

    if (raw.indexOf('..') !== -1) {
        frappe.msgprint({
            title: __('Invalid Email Address'),
            indicator: 'red',
            message: `<b>${label}</b> cannot contain consecutive dots ('<b>..</b>').`
        });
        frappe.validated = false;
        return false;
    }

    return true;
}

