frappe.ui.form.on('Employee', {
    validate: function(frm) {
        // Runs STRICTLY ONLY during saving (when clicking Save)
        let doj = frm.doc.date_of_joining ? frappe.datetime.str_to_obj(frm.doc.date_of_joining) : null;
        let doj_display = frm.doc.date_of_joining ? frappe.datetime.str_to_user(frm.doc.date_of_joining) : '';

        // 1. Validate Increment History: Date of Issue must be > Date of Joining
        if (doj) {
            for (let row of (frm.doc.custom_increment_history || [])) {
                if (row.date_of_issue) {
                    let issue_dt = frappe.datetime.str_to_obj(row.date_of_issue);
                    if (issue_dt <= doj) {
                        let issue_display = frappe.datetime.str_to_user(row.date_of_issue);
                        frappe.msgprint({
                            title: __('Invalid Increment Date'),
                            indicator: 'red',
                            message: __('<b>Increment History (Row #{0}):</b> Date of Issue (<b>{1}</b>) must be greater than Date of Joining (<b>{2}</b>). An employee cannot receive an increment on or before their joining date.', [row.idx || 1, issue_display, doj_display])
                        });
                        frappe.validated = false;
                        return false;
                    }
                }
            }
        }

        // 2. Validate Organization Associations: Effective From must be >= Date of Joining
        for (let row of (frm.doc.custom_organization_associations || [])) {
            if (row.effective_from) {
                let eff_dt = frappe.datetime.str_to_obj(row.effective_from);
                if (doj && eff_dt < doj) {
                    let eff_display = frappe.datetime.str_to_user(row.effective_from);
                    frappe.msgprint({
                        title: __('Invalid Effective From Date'),
                        indicator: 'red',
                        message: __('<b>Organization Associations (Row #{0}):</b> Effective From date (<b>{1}</b>) must be greater than or equal to Date of Joining (<b>{2}</b>).', [row.idx || 1, eff_display, doj_display])
                    });
                    frappe.validated = false;
                    return false;
                }

                // Auto-adjust Effective To if it is older than Effective From
                if (row.effective_to) {
                    let to_dt = frappe.datetime.str_to_obj(row.effective_to);
                    if (to_dt < eff_dt) {
                        let from_year = row.effective_from.split('-')[0];
                        row.effective_to = `${from_year}-12-31`;
                    }
                }
            }
        }

        // 3. Validate Last 3 Months Payslip: Date must be < Date of Joining
        if (doj) {
            for (let row of (frm.doc.custom_last_3_months_payslip || [])) {
                if (row.date) {
                    let payslip_dt = frappe.datetime.str_to_obj(row.date);
                    if (payslip_dt >= doj) {
                        let payslip_display = frappe.datetime.str_to_user(row.date);
                        frappe.msgprint({
                            title: __('Invalid Payslip Date'),
                            indicator: 'red',
                            message: __('<b>Last 3 Months Payslip (Row #{0}):</b> Date (<b>{1}</b>) must be earlier than Date of Joining (<b>{2}</b>).', [row.idx || 1, payslip_display, doj_display])
                        });
                        frappe.validated = false;
                        return false;
                    }
                }
            }
        }

        // 4. Validate Position/Role Tracker (internal_work_history):
        // - From Date must be >= Date of Joining
        // - To Date must be > From Date
        for (let row of (frm.doc.internal_work_history || [])) {
            let from_dt = row.from_date ? frappe.datetime.str_to_obj(row.from_date) : null;
            let to_dt = row.to_date ? frappe.datetime.str_to_obj(row.to_date) : null;

            if (from_dt && doj && from_dt < doj) {
                let from_display = frappe.datetime.str_to_user(row.from_date);
                frappe.msgprint({
                    title: __('Invalid Position/Role Tracker Date'),
                    indicator: 'red',
                    message: __('<b>Position/Role Tracker (Row #{0}):</b> From Date (<b>{1}</b>) must be greater than or equal to Date of Joining (<b>{2}</b>).', [row.idx || 1, from_display, doj_display])
                });
                frappe.validated = false;
                return false;
            }

            if (from_dt && to_dt && to_dt <= from_dt) {
                let to_display = frappe.datetime.str_to_user(row.to_date);
                let from_display = frappe.datetime.str_to_user(row.from_date);
                frappe.msgprint({
                    title: __('Invalid Position/Role Tracker Date'),
                    indicator: 'red',
                    message: __('<b>Position/Role Tracker (Row #{0}):</b> To Date (<b>{1}</b>) must be greater than From Date (<b>{2}</b>).', [row.idx || 1, to_display, from_display])
                });
                frappe.validated = false;
                return false;
            }
        }
    }
});

