        if (frm.doc.ifsc_code) {
            let ifsc = (frm.doc.ifsc_code || '').trim().toUpperCase();
            frm.doc.ifsc_code = ifsc;

            // RBI Standard IFSC Format:
            // 4 Alphabetic characters (Bank Code)
            // 1 Numeric Zero '0' (Control Character)
            // 6 Alphanumeric characters (Branch Code)
            let ifsc_regex = /^[A-Z]{4}0[A-Z0-9]{6}$/;

            if (!ifsc_regex.test(ifsc)) {
                frappe.msgprint({
                    title: __('Invalid IFSC Code'),
                    indicator: 'red',
                    message: __(
                        '<b>IFSC Code</b> must be a valid 11-character code in the standard RBI format <b>AAAA0BBBBBB</b>:<br><br>' +
                        '• <b>First 4 characters:</b> Bank Code (letters only, e.g., <code>BARB</code>, <code>SBIN</code>, <code>ICIC</code>)<br>' +
                        '• <b>5th character:</b> Must be the number zero (<b>0</b>), not the letter "O"<br>' +
                        '• <b>Last 6 characters:</b> Branch Code (alphanumeric, e.g., <code>VJMDHP</code> or <code>000123</code>)<br><br>' +
                        'Entered Value: <b>{0}</b>',
                        [ifsc]
                    )
                });
                frappe.validated = false;
                return false;
            }
        }
    }
});

