                        '• <b>Characters 3–4:</b> 2 check digits (numbers <code>0-9</code>)<br>' +
                        '• <b>Remaining 11–30 characters:</b> Basic Bank Account Number (letters & numbers)<br><br>' +
                        'Entered Value: <b>{0}</b>',
                        [iban]
                    )
                });
                frappe.validated = false;
                return false;
