        if (!frm.custom_modules_multicheck) return;

        if (frm.doc.custom_module_profile) {
            frappe.db.get_doc("Module Profile", frm.doc.custom_module_profile).then(profile_doc => {
                let blocked_in_profile = (profile_doc.block_modules || []).map(b => b.module);
                let all_mods = frm._all_system_modules || [];
                let allowed = all_mods.filter(m => !blocked_in_profile.includes(m));
                frm.custom_modules_multicheck.selected_options = allowed;
                frm.custom_modules_multicheck.refresh_input();
                frm.set_value('custom_blocked_modules', JSON.stringify(blocked_in_profile));
                frm.dirty();
            });
        }
    },
    validate: function(frm) {
        // Clean up user_id if it somehow retained display format "Name [ email ]"
        if (frm.doc.user_id && frm.doc.user_id.includes(' [') && frm.doc.user_id.endsWith(']')) {
            let match = frm.doc.user_id.match(/\[\s*(.*?)\s*\]/);
            if (match && match[1]) {
                frm.doc.user_id = match[1].trim();
            }
        }

        // Validate email format ONLY if an email has been typed in
        if (frm.doc.custom_user_option === 'Create New User' && !frm.doc.user_id) {
            let email = (frm.doc.custom_new_user_email || '').trim();
            if (email && !frappe.utils.validate_type(email, 'email')) {
                frappe.msgprint(__('Please provide a valid email address in New User Email.'));
                frappe.validated = false;
                return false;
            }
        }

        if (frm.custom_role_multicheck) {
            let checked_roles = frm.custom_role_multicheck.get_checked_options();
            if (frappe.session.user !== 'Administrator' && checked_roles.includes('System Manager')) {
                frappe.msgprint(__('Only the Administrator can assign the System Manager role.'));
                frappe.validated = false;
                return false;
            }
            frm.doc.custom_assigned_roles = JSON.stringify(checked_roles);
        }
        if (frm.custom_modules_multicheck) {
            let unchecked_modules = frm.custom_modules_multicheck.get_unchecked_options();
            frm.doc.custom_blocked_modules = JSON.stringify(unchecked_modules);
        }
    }
});

function sync_default_new_user_email(frm) {
    if (frm.doc.custom_user_option === 'Create New User' && !frm.doc.user_id && !frm.doc.custom_new_user_email) {
        let default_email = frm.doc.company_email || frm.doc.prefered_email || frm.doc.personal_email || '';
        if (default_email) {
            frm.doc.custom_new_user_email = default_email;
            if (frm.fields_dict.custom_new_user_email) {
                frm.fields_dict.custom_new_user_email.set_input(default_email);
            }
        }
    }
}

function toggle_user_account_fields(frm) {
    frm.toggle_display('create_user', false);

    let has_user = Boolean(frm.doc.user_id);

    if (has_user) {
        frm.toggle_display('custom_user_option', false);
        frm.toggle_display('user_id', true);
        frm.toggle_display('custom_new_user_email', false);
        frm.toggle_display('custom_send_welcome_email', false);
    } else {
        if (!frm.doc.custom_user_option) {
            if (frm.is_new()) {
                frm.doc.custom_user_option = 'Create New User';
            } else {
                frm.doc.custom_user_option = 'Create New User';
            }
        }

        frm.toggle_display('custom_user_option', true);
        let is_create = frm.doc.custom_user_option === 'Create New User';

        frm.toggle_display('user_id', !is_create);
        frm.toggle_display('custom_new_user_email', is_create);
        frm.toggle_display('custom_send_welcome_email', is_create);

        sync_default_new_user_email(frm);
    }
}

function setup_user_id_display_and_rename(frm) {
    if (!frm.fields_dict || !frm.fields_dict.user_id) return;
    let $wrapper = frm.fields_dict.user_id.$wrapper;
    $wrapper.find('.user-rename-btn').remove();

    if (!frm.doc.user_id) {
        let $input = frm.fields_dict.user_id.$input;
        if ($input && $input.length) {
            $input.prop('readonly', false).css({
                'cursor': 'text',
                'background-color': '',
                'width': '100%'
            });
        }
        return;
    }

    let user_id = frm.doc.user_id;
    let control = frm.fields_dict.user_id;

    // Adjust column widths so User ID column has ample room (65% vs 35%)
    let $col = $wrapper.closest('.form-column');
    let $next_col = $col.next('.form-column');
    if ($col.length && $next_col.length) {
        $col.css({
            'flex': '1.35 1 0%',
            'max-width': '65%'
        });
        $next_col.css({
            'flex': '0.85 1 0%',
            'max-width': '35%'
        });
    }

    // 1. Format display in input as: Name [ email ]
    frappe.db.get_value('User', user_id, ['full_name', 'email'], function(r) {
        if (r && r.email) {
            let display_text = r.email || user_id;
            if (!control.title_value_map) {
                control.title_value_map = {};
            }
            control.title_value_map[display_text] = user_id;
            control.set_input_value(display_text);

            let $input = control.$input;
            if ($input && $input.length) {
                $input.val(display_text);
                $input.attr('title', display_text);
                $input.prop('readonly', true).css({
                    'cursor': 'default',
                    'background-color': 'var(--control-bg, #f8f9fa)',
                    'width': '100%',
                    'font-size': '13px'
                });
            }
        }
    });

    // 2. Add [ ✏️ Change ] button right next to input
    let user_roles_rename = (frappe.user_roles && Array.isArray(frappe.user_roles)) ? frappe.user_roles : ((frappe.boot && frappe.boot.user && frappe.boot.user.roles) || []);
    let can_rename = frappe.session.user === 'Administrator' ||
        user_roles_rename.some(r => ['System Manager', 'Administrator', 'HR Manager', 'HR User'].includes(r));

    if (!can_rename) return;

    let icon_html = (frappe.utils && frappe.utils.icon) 
        ? frappe.utils.icon('edit', 'xs') 
        : '<i class="fa fa-pencil" style="font-size: 11px;"></i>';

    let $btn = $(`
        <button class="btn btn-default btn-xs user-rename-btn" type="button" 
            style="margin-left: 8px; padding: 4px 10px; display: inline-flex; align-items: center; gap: 5px; border-radius: var(--border-radius-sm); font-size: 12px; font-weight: 500; cursor: pointer; white-space: nowrap; height: 28px; flex-shrink: 0;" 
            title="${__('Change / Rename User ID')}">
            ${icon_html}
            <span>${__('Change')}</span>
        </button>
    `);

    $btn.on('click', function(e) {
        e.preventDefault();
        prompt_user_id_change(frm);
    });

    let $control_input = $wrapper.find('.control-input');
    if ($control_input.length) {
        $control_input.show().css({
            'display': 'flex',
            'align-items': 'center',
            'width': '100%'
        });

        // Ensure the link-field div expands to take all available flex width
        let $link_field = $wrapper.find('.link-field');
        if ($link_field.length) {
            $link_field.css({
                'flex': '1 1 auto',
                'width': '100%',
                'min-width': '0'
            });
        }

        $control_input.append($btn);
    }
}

function prompt_user_id_change(frm) {
    if (!frm.doc.user_id) return;
    let old_user_id = frm.doc.user_id;

    frappe.prompt({
        label: __('New Email / User ID'),
        fieldname: 'new_email',
        fieldtype: 'Data',
        reqd: 1,
        default: old_user_id
    }, function(values) {
        let new_email = (values.new_email || '').trim().toLowerCase();
        if (!new_email || new_email === old_user_id.toLowerCase()) return;

        if (!frappe.utils.validate_type(new_email, 'email')) {
            frappe.msgprint(__('Please enter a valid email address.'));
            return;
        }

        frappe.confirm(
            __('Are you sure you want to change User ID from <b>{0}</b> to <b>{1}</b>?<br><br><small class="text-muted">This will update the User account and all linked employee records and permissions.</small>', [old_user_id, new_email]),
            function() {
                frappe.call({
                    method: 'frappe.client.rename_doc',
                    args: {
                        doctype: 'User',
                        old_name: old_user_id,
                        new_name: new_email,
                        merge: false
                    },
                    freeze: true,
                    freeze_message: __('Renaming User ID...'),
                    callback: function(r) {
                        if (!r.exc) {
                            frappe.show_alert({
                                message: __('User ID renamed successfully to {0}', [new_email]),
                                indicator: 'green'
                            });
                            frm.reload_doc();
                        }
                    }
                });
            }
        );
    }, __('Change User ID / Email'), __('Update'));
}

function setup_employee_access_editors(frm) {
    if (!frm.fields_dict || !frm.fields_dict.custom_roles_html || !frm.fields_dict.custom_modules_html) return;

    let user_roles_edit = (frappe.user_roles && Array.isArray(frappe.user_roles)) ? frappe.user_roles : ((frappe.boot && frappe.boot.user && frappe.boot.user.roles) || []);
    let can_edit = user_roles_edit.some(r => ['System Manager', 'Administrator', 'HR Manager', 'HR User'].includes(r));

    let roles_field = frm.fields_dict.custom_roles_html;
    let modules_field = frm.fields_dict.custom_modules_html;

    let $roles_wrapper = $(roles_field.wrapper).empty();
    let $modules_wrapper = $(modules_field.wrapper).empty();

    let $roles_container = $('<div class="employee-roles-wrapper" style="margin-top: 5px; margin-bottom: 15px;"></div>').appendTo($roles_wrapper);
    let $modules_container = $('<div class="employee-modules-wrapper" style="margin-top: 5px; margin-bottom: 15px;"></div>').appendTo($modules_wrapper);

    // Use cached roles/modules if available for instant load
    let fetch_roles = frappe._cached_all_roles ?
        Promise.resolve(frappe._cached_all_roles) :
        frappe.xcall("frappe.core.doctype.user.user.get_all_roles").then(r => { frappe._cached_all_roles = r; return r; });

    let fetch_modules = frappe._cached_all_modules ?
        Promise.resolve(frappe._cached_all_modules) :
        frappe.db.get_list("Module Def", { fields: ["name"], order_by: "name asc", limit: 100 }).then(m => { frappe._cached_all_modules = m; return m; });

    let fetch_user = frm.doc.user_id ? 
        frappe.xcall("access_custom.employee_contract_validation.get_user_roles_and_modules", { user_id: frm.doc.user_id }) : 
        Promise.resolve(null);

    Promise.all([fetch_roles, fetch_modules, fetch_user]).then(([all_roles, modules_data, user_data]) => {
        let all_modules = (modules_data || []).map(m => m.name || m);
        frm._all_system_modules = all_modules;

        // 1. ROLES SETUP
        let selected_roles = [];
        if (user_data && user_data.roles && user_data.roles.length > 0) {
            selected_roles = user_data.roles;
            let roles_str = JSON.stringify(selected_roles);
            if (frm.doc.custom_assigned_roles !== roles_str) {
                frm.doc.custom_assigned_roles = roles_str;
            }
            if (user_data.role_profile_name && frm.doc.custom_role_profile !== user_data.role_profile_name) {
                frm.doc.custom_role_profile = user_data.role_profile_name;
            }
        } else if (frm.doc.custom_assigned_roles) {
            try { selected_roles = JSON.parse(frm.doc.custom_assigned_roles); } catch(e) {}
        }
        if (!selected_roles || selected_roles.length === 0) {
            selected_roles = ['Employee', 'Employee Self Service'];
        }

        $roles_container.empty();
        let available_roles = (all_roles || []);
        if (frappe.session.user !== 'Administrator') {
            available_roles = available_roles.filter(r => r !== 'System Manager');
        }
        let roles_multicheck = frappe.ui.form.make_control({
            parent: $roles_container,
            df: {
                fieldname: "custom_roles_multicheck",
                fieldtype: "MultiCheck",
                select_all: true,
                columns: "15rem",
                options: available_roles.map(role => ({
                    label: __(role),
                    value: role,
                    checked: selected_roles.includes(role)
                })),
                on_change: function() {
                    let checked = roles_multicheck.get_checked_options();
                    frm.set_value('custom_assigned_roles', JSON.stringify(checked));
                    frm.dirty();
                }
            },
            render_input: true
        });
        frm.custom_role_multicheck = roles_multicheck;
        if (!can_edit) {
            $roles_container.find('input[type="checkbox"]').prop('disabled', true);
            $roles_container.find('.btn').prop('disabled', true);
        }

        // 2. MODULES SETUP (Checked = Allowed, Unchecked = Blocked)
        let blocked_modules = [];
        if (user_data && user_data.blocked_modules) {
            blocked_modules = user_data.blocked_modules;
            let blocked_str = JSON.stringify(blocked_modules);
            if (frm.doc.custom_blocked_modules !== blocked_str) {
                frm.doc.custom_blocked_modules = blocked_str;
            }
            if (user_data.module_profile && frm.doc.custom_module_profile !== user_data.module_profile) {
                frm.doc.custom_module_profile = user_data.module_profile;
            }
        } else if (frm.doc.custom_blocked_modules) {
            try { blocked_modules = JSON.parse(frm.doc.custom_blocked_modules); } catch(e) {}
        }

        $modules_container.empty();
        let modules_multicheck = frappe.ui.form.make_control({
            parent: $modules_container,
            df: {
                fieldname: "custom_modules_multicheck",
                fieldtype: "MultiCheck",
                select_all: true,
                columns: "15rem",
                options: all_modules.map(mod => ({
                    label: __(mod),
                    value: mod,
                    checked: !blocked_modules.includes(mod)
                })),
                on_change: function() {
                    let unchecked = modules_multicheck.get_unchecked_options();
                    frm.set_value('custom_blocked_modules', JSON.stringify(unchecked));
                    frm.dirty();
                }
            },
            render_input: true
        });
        frm.custom_modules_multicheck = modules_multicheck;
        if (!can_edit) {
            $modules_container.find('input[type="checkbox"]').prop('disabled', true);
            $modules_container.find('.btn').prop('disabled', true);
        }
    }).catch(err => {
        console.error("Error setting up roles/modules editors:", err);
    });
}

frappe.ui.form.on('User', {
