                    indicator: 'red'
                });
                frappe.validated = false;
                return false;
            }
        }
    }
});

function add_email_rename_button(frm) {
    if (!frm.fields_dict || !frm.fields_dict.email) return;

    let $wrapper = frm.fields_dict.email.$wrapper;
    $wrapper.find('.email-rename-btn').remove();

    // Only for saved users, not new, not Administrator
    if (frm.is_new() || frm.doc.name === 'Administrator') return;

    let can_rename = frappe.session.user === 'Administrator' ||
        frappe.user_roles.some(r => ['System Manager', 'Administrator', 'HR Manager', 'HR User'].includes(r));

    if (!can_rename) return;

    // Hide duplicate .control-value (the second grey box)
    $wrapper.find('.control-value').hide();

    let $input = frm.fields_dict.email.$input;
    if ($input && $input.length) {
        $input.prop('readonly', true).css({
            'cursor': 'default',
            'background-color': 'var(--control-bg, #f8f9fa)'
        });
    }

    let icon_html = (frappe.utils && frappe.utils.icon) 
        ? frappe.utils.icon('edit', 'xs') 
        : '<i class="fa fa-pencil" style="font-size: 11px;"></i>';

    let $btn = $(`
        <button class="btn btn-default btn-xs email-rename-btn" type="button" 
            style="margin-left: 8px; padding: 4px 10px; display: inline-flex; align-items: center; gap: 5px; border-radius: var(--border-radius-sm); font-size: 12px; font-weight: 500; cursor: pointer; white-space: nowrap; height: 28px;" 
            title="${__('Change / Rename Email Address')}">
            ${icon_html}
            <span>${__('Change')}</span>
        </button>
    `);

    $btn.on('click', function(e) {
        e.preventDefault();
        frm.rename_doc();
    });

    let $control_input = $wrapper.find('.control-input');
    if ($control_input.length) {
        $control_input.show().css({
            'display': 'flex',
            'align-items': 'center'
        });
        $control_input.append($btn);
    }
}

function enforce_system_manager_protection(frm) {
    frm._original_roles = (frm.doc.roles || []).map(r => r.role);

    if (frappe.session.user === 'Administrator') return;

    // Periodically disable System Manager checkbox in roles grid for non-admin
    let disable_sm = function() {
        if (!frm.fields_dict || !frm.fields_dict.roles) return;
        let $w = frm.fields_dict.roles.$wrapper;
        $w.find('input[type="checkbox"]').each(function() {
            let $cb = $(this);
            let label = $cb.closest('label').text().trim() || $cb.val() || '';
            if (label.indexOf('System Manager') !== -1) {
                $cb.prop('disabled', true);
                $cb.closest('div').attr('title', __('Only Administrator can assign the System Manager role.'));
            }
        });
    };

    setTimeout(disable_sm, 300);
    setTimeout(disable_sm, 1000);
}

frappe.ui.form.on('Employee', {
    setup: function(frm) {
        frm.set_query('custom_active_contract', function() {
            return {
                query: 'access_custom.employee_contract_validation.get_available_consultant_contracts',
                filters: {
                    'current_employee': frm.doc.name || ''
                }
            };
        });

        frm.set_query('custom_active_employee_contract', function() {
            return {
                query: 'access_custom.employee_contract_validation.get_available_employee_contracts',
                filters: {
                    'current_employee': frm.doc.name || ''
                }
            };
        });
    },

    refresh: function(frm) {
        let is_new = frm.is_new();
        frm.toggle_display('custom_contract_type', is_new);
        frm.toggle_display('custom_col_break_contract', is_new);
        frm.toggle_display('custom_col_break_contract_select', is_new);
        frm.toggle_display('custom_active_contract', is_new && frm.doc.custom_contract_type === 'Consultant Contract');
        frm.toggle_display('custom_active_employee_contract', is_new && frm.doc.custom_contract_type === 'Employee Contract');
    },

    custom_contract_type: function(frm) {
        let is_new = frm.is_new();
        frm.set_value('custom_active_contract', null);
        frm.set_value('custom_active_employee_contract', null);
        frm.toggle_display('custom_active_contract', is_new && frm.doc.custom_contract_type === 'Consultant Contract');
        frm.toggle_display('custom_active_employee_contract', is_new && frm.doc.custom_contract_type === 'Employee Contract');
    },

    custom_active_contract: function(frm) {
        if (!frm.doc.custom_active_contract) return;

        frappe.db.get_doc('Consultant Contract', frm.doc.custom_active_contract).then(contract => {
            if (!contract) return;

            // 1. Name parsing (First Name, Middle Name, Last Name, Full Name)
            if (contract.consultant_name) {
                let fullName = contract.consultant_name.trim();
                let parts = fullName.split(/\s+/);
                if (parts.length === 1) {
                    frm.set_value('first_name', parts[0]);
                } else if (parts.length === 2) {
                    frm.set_value('first_name', parts[0]);
                    frm.set_value('last_name', parts[1]);
                } else if (parts.length > 2) {
                    frm.set_value('first_name', parts[0]);
                    frm.set_value('middle_name', parts.slice(1, -1).join(' '));
                    frm.set_value('last_name', parts[parts.length - 1]);
                }
                frm.set_value('employee_name', fullName);
            }

            // 2. Email & Contact Number
            if (contract.email_id) {
                frm.set_value('personal_email', contract.email_id);
            }
            if (contract.contact_number) {
                frm.set_value('cell_number', contract.contact_number);
            }

            // 3. Employee CV
            if (contract.consultant_cv && !frm.doc.custom_employee_cv) {
                frm.set_value('custom_employee_cv', contract.consultant_cv);
            }

            // 4. Structured Address
            if (contract.address_line_1) frm.set_value('custom_address_line_1', contract.address_line_1);
            if (contract.address_line_2) frm.set_value('custom_address_line_2', contract.address_line_2);
            if (contract.city) frm.set_value('custom_city', contract.city);
            if (contract.state) frm.set_value('custom_state', contract.state);
            if (contract.pin_code) frm.set_value('custom_pin_code', contract.pin_code);

            // 5. Employment Details
            if (contract.start_date) {
                frm.set_value('date_of_joining', contract.start_date);
            }
            frm.set_value('employment_type', 'Full Time Consultant');

            let org = contract.requesting_organization || contract.organization;
            if (org) {
                frm.set_value('company', org);
            }
            if (contract.requesting_department) {
                frm.set_value('department', contract.requesting_department);
            }
            if (contract.project_manager) {
                frm.set_value('reports_to', contract.project_manager);
            } else if (contract.team_lead) {
                frm.set_value('reports_to', contract.team_lead);
            }
            if (contract.designation) {
                frm.set_value('designation', contract.designation);
            }

            frappe.show_alert({
                message: __(`Data auto-populated from Active Contract <b>${contract.name}</b>`),
                indicator: 'green'
            }, 5);
        });
    },

    custom_active_employee_contract: function(frm) {
        if (!frm.doc.custom_active_employee_contract) return;

        frappe.db.get_doc('Contract', frm.doc.custom_active_employee_contract).then(contract => {
            if (!contract) return;
            if (contract.party_name) {
                frm.set_value('employee_name', contract.party_name);
                let parts = contract.party_name.trim().split(/\s+/);
                if (parts.length === 1) {
                    frm.set_value('first_name', parts[0]);
                } else if (parts.length >= 2) {
                    frm.set_value('first_name', parts[0]);
                    frm.set_value('last_name', parts[parts.length - 1]);
                }
            }
            if (contract.start_date) {
                frm.set_value('date_of_joining', contract.start_date);
            }
            frm.set_value('employment_type', 'Employee');

            frappe.show_alert({
                message: __(`Data auto-populated from Active Contract <b>${contract.name}</b>`),
                indicator: 'green'
            }, 5);
        });
    }
});

frappe.ui.form.on('Customer', {
    refresh: function(frm) {
        toggle_inactivation_reason(frm);
    },
    custom_status: function(frm) {
        toggle_inactivation_reason(frm);
        if (frm.doc.custom_status === 'Active') {
            // When customer is set to Active, clear any old inactivation reason
            frm.set_value('custom_reason_for_inactivation', '');
        } else if (frm.doc.custom_status === 'Inactive') {
            // Always ask for a fresh reason when changing status to Inactive
            frappe.prompt([
                {
                    label: __('Reason for Inactivation'),
                    fieldname: 'reason',
                    fieldtype: 'Small Text',
                    reqd: 1,
                    description: __('Mandatory: Please explain why this customer is being marked inactive.')
                }
            ], function(values) {
                frm.set_value('custom_reason_for_inactivation', values.reason);
            }, __('Reason for Inactivation Required'), __('Confirm Inactivation'));
        }
    },
    validate: function(frm) {
        if (frm.doc.custom_status === 'Inactive') {
            let reason = (frm.doc.custom_reason_for_inactivation || '').trim();
            if (!reason) {
                frappe.msgprint({
                    title: __('Reason Required'),
                    indicator: 'red',
                    message: __('<b>Reason for Inactivation</b> is mandatory before marking this Customer as <b>Inactive</b>.')
                });
                frappe.validated = false;
            }
        }
    }
});

function toggle_inactivation_reason(frm) {
    let is_inactive = (frm.doc.custom_status === 'Inactive');
    frm.set_df_property('custom_reason_for_inactivation', 'reqd', is_inactive ? 1 : 0);
    frm.set_df_property('custom_reason_for_inactivation', 'hidden', is_inactive ? 0 : 1);
}

// ============================================================
// EMPLOYEE PAYSLIPS MONTH (MM-YYYY) PICKER & VALIDATION
// ============================================================

frappe.ui.form.on('Employee', {
    refresh: function(frm) {
        setup_payslip_month_picker(frm);
    },
    onload_post_render: function(frm) {
        setup_payslip_month_picker(frm);
    },
    validate: function(frm) {
        // Enforce MM-YYYY format on all rows in Last 3 Months Payslip
        for (let row of (frm.doc.custom_last_3_months_payslip || [])) {
            if (row.date) {
                let val = String(row.date).trim();
                let regex = /^(0[1-9]|1[0-2])-\d{4}$/;
                if (!regex.test(val)) {
                    frappe.msgprint({
                        title: __('Invalid Month Format'),
                        indicator: 'red',
                        message: __('<b>Last 3 Months Payslip (Row #{0}):</b> Date must be in <b>MM-YYYY</b> format (e.g. <b>11-2026</b>).', [row.idx || 1])
                    });
                    frappe.validated = false;
                    return false;
                }
            }
        }
    }
});

frappe.ui.form.on('Employee Payslips', {
    date: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row && row.date) {
            let clean = String(row.date).replace(/[\/\.]/g, '-').trim();
            // Auto-format 6 digits e.g. 112026 -> 11-2026
            if (/^\d{6}$/.test(clean)) {
                clean = clean.substring(0, 2) + '-' + clean.substring(2);
            }
            if (row.date !== clean) {
                frappe.model.set_value(cdt, cdn, 'date', clean);
            }
        }
    },
    form_render: function(frm, cdt, cdn) {
        let grid = frm.get_field('custom_last_3_months_payslip');
        if (grid && grid.grid && grid.grid.grid_rows_by_docname) {
            let row_obj = grid.grid.grid_rows_by_docname[cdn];
            if (row_obj && row_obj.grid_form) {
                let fld = row_form_field(row_obj, 'date');
                if (fld && fld.$input) {
                    init_month_picker(fld.$input);
                }
            }
        }
    }
});

function row_form_field(row_obj, fieldname) {
    if (row_obj.grid_form && row_obj.grid_form.fields_dict) {
        return row_obj.grid_form.fields_dict[fieldname];
    }
    return null;
}

function init_month_picker($input) {
    if (!$input || $input.data('has_month_picker')) return;
    $input.attr('placeholder', 'MM-YYYY');
    $input.attr('maxlength', 7);
    $input.data('has_month_picker', true);

    if ($.fn.datepicker) {
        $input.datepicker({
            language: 'en',
            autoClose: true,
            minView: 'months',
            view: 'months',
            dateFormat: 'mm-yyyy',
            onSelect: function(formattedDate) {
                $input.val(formattedDate).trigger('input').trigger('change');
            }
        });
    }
}

function setup_payslip_month_picker(frm) {
    let grid_field = frm.get_field('custom_last_3_months_payslip');
    if (!grid_field || !grid_field.grid) return;

    let $wrapper = $(grid_field.grid.wrapper);

    // Grid column placeholder & picker on focus
    $wrapper.off('focus.payslip_month', 'input[data-fieldname="date"]').on('focus.payslip_month', 'input[data-fieldname="date"]', function() {
        let $inp = $(this);
        init_month_picker($inp);
        let dp = $inp.data('datepicker');
        if (dp && !dp.visible) {
            dp.show();
        }
    });

    // Also format on blur if user typed
    $wrapper.off('blur.payslip_month', 'input[data-fieldname="date"]').on('blur.payslip_month', 'input[data-fieldname="date"]', function() {
        let $inp = $(this);
        let val = ($inp.val() || '').replace(/[\/\.]/g, '-').trim();
        if (/^\d{6}$/.test(val)) {
            val = val.substring(0, 2) + '-' + val.substring(2);
            $inp.val(val).trigger('input').trigger('change');
        }
    });
}
